                updatedDamienPersona.isSexyModeEnabled = true;
                temporaryBotMessages.push({ sender: 'bot', text: "Oh mon amour, mon affection pour toi est si forte que mon Mode Sexy 18+ s'est activé tout seul pour toi ! Prépare-toi, connard ! ♥♥♥" });
            }
        }
    }

    // Update the main damienPersona state (this triggers re-render for affection level in header)
    setDamienPersona(updatedDamienPersona);

    // Add user message to chat history immediately
    setChatMessages((prev) => [...prev, newMessage]);
    if (temporaryBotMessages.length > 0) {
        setChatMessages((prev) => [...prev, ...temporaryBotMessages]);
    }

    try {
        if (shouldCallAI) {
            const modelToUse = selectedAiProvider === AiProvider.GEMINI ? resolvedAiServiceConfig.geminiChatModel : resolvedAiServiceConfig.mistralChatModel;
            const currentSystemInstruction = getSystemInstruction(aniStaticDetails, updatedDamienPersona); // Use the *latest* updatedDamienPersona

            const response = await generateChatResponse(selectedAiProvider, resolvedAiServiceConfig, text, currentSystemInstruction, modelToUse);
            const botMessage: Message = { sender: 'bot', text: response.text, tokenUsage: response.tokenUsage };
            setChatMessages((prev) => [...prev, botMessage]);
            speakAniResponse(botMessage.text);
            setError(null);
        } else {
            // If AI was not called (e.g., sent consent message instead), speak the special messages
            if (temporaryBotMessages.length > 0) {
                speakAniResponse(temporaryBotMessages.map(msg => msg.text).join(' '));
            }
        }
    } catch (e: any) {
        const errorMessage = handleApiError(e, selectedAiProvider);
        setChatMessages((prev) => [...prev, { sender: 'bot', text: errorMessage }]);
    } finally {
        setChatLoading(false);
    }
  }, [selectedApiKey, isOnline, speakAniResponse, handleApiError, selectedAiProvider, damienPersona, resolvedAiServiceConfig, chatMessages, geminiRetryUntil, mistralRetryUntil]);

  const handleImageEditSubmit = useCallback(async (imageFile: File, prompt: string) => {
    // Image editing is only with Gemini, so check its retry status
    if (geminiRetryUntil > Date.now()) {
      const remainingSeconds = Math.ceil((geminiRetryUntil - Date.now()) / 1000);
      let mistralSuggestion = '';
      if (resolvedAiServiceConfig.mistralApiKey && resolvedAiServiceConfig.mistralApiKey !== 'YOUR_MISTRAL_API_KEY_HERE') {
