  geminiRetryTimeRemaining: number;
  mistralRetryTimeRemaining: number; // New prop for Mistral retry time
  selectedAiProvider: AiProvider; // New prop to know current provider
}

const ChatView: React.FC<ChatViewProps> = ({
  messages,
