import { AiProvider, getAiServiceConfig, ResolvedAiServiceConfig, CHAT_MAX_OUTPUT_TOKENS, GEMINI_THINKING_BUDGET, MISTRAL_MAX_TOKENS_DIRECT } from '../constants/aniPersona'; // Updated import to use getAiServiceConfig and ResolvedAiServiceConfig

interface ChatResponse {
  text: string;
  tokenUsage: TokenUsage;
}

interface ImageEditResponse {
  base64Image: string;
  tokenUsage: TokenUsage;
}

/**
 * Generates a chat response from the selected AI model (Gemini or Mistral).
 * @param provider The selected AI provider.
 * @param resolvedConfig The resolved AI service configuration.
 * @param prompt The user's message.
 * @param systemInstruction The system instruction for the chat.
 * @param modelName The name of the AI model to use for chat.
 * @returns The text response and token usage.
 */
export async function generateChatResponse(
  provider: AiProvider,
  resolvedConfig: ResolvedAiServiceConfig, // Now accepts the resolved config
  prompt: string,
  systemInstruction: string,
  modelName: string
): Promise<ChatResponse> {
  if (provider === AiProvider.GEMINI) {
    const geminiApiKey = resolvedConfig.geminiApiKey; // Get from resolved config
    if (!geminiApiKey) {
      // This case should ideally be caught by App.tsx's API key selection check
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
    }
    try {
      const ai = new GoogleGenAI({ apiKey: geminiApiKey });
      const chat = ai.chats.create({
        model: modelName, // This will be resolvedConfig.geminiChatModel
        config: {
          systemInstruction: systemInstruction,
          maxOutputTokens: CHAT_MAX_OUTPUT_TOKENS, // Enforce shorter responses
          thinkingConfig: { thinkingBudget: GEMINI_THINKING_BUDGET }, // Reserve tokens for thinking
        },
      });

      const response: GenerateContentResponse = await chat.sendMessage({ message: prompt });
      const text = response.text || "Ani est muette, c'est ouf ! ♥♥";
      const promptTokens = response.usageMetadata?.promptTokenCount || 0;
      const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
      const totalTokens = promptTokens + completionTokens;

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
      };
    } catch (error: any) {
      console.error("Erreur Gemini Chat:", error);
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
    }
  } else if (provider === AiProvider.MISTRAL) {
    const mistralApiKey = resolvedConfig.mistralApiKey; // Get from resolved config
    const mistralApiUrl = resolvedConfig.mistralApiUrl; // Get from resolved config

    if (!mistralApiKey || mistralApiKey === 'YOUR_MISTRAL_API_KEY_HERE') {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "Clé API Mistral manquante ou non configurée. Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`, bordel !",
        code: 401
      }));
    }
    if (!mistralApiUrl) {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "URL API Mistral manquante ou non configurée. Modifie le champ 'URL API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_URL`, connard !",
        code: 400 // Assuming 400 for bad URL config, or custom code
      }));
    }

    try {
      const response = await fetch(mistralApiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${mistralApiKey}`,
        },
        body: JSON.stringify({
          model: modelName, // This will be resolvedConfig.mistralChatModel
          messages: [{ role: 'user', content: systemInstruction ? `${systemInstruction}\n${prompt}` : prompt }],
          max_tokens: MISTRAL_MAX_TOKENS_DIRECT, // Enforce shorter responses for Mistral
          // Mistral doesn't have a direct 'systemInstruction' in the /chat/completions endpoint
          // For now, prepending to the user prompt if systemInstruction exists.
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        const errorDetails: any = { type: AiProvider.MISTRAL, message: errorData.message || response.statusText, code: response.status, errorDetails: errorData };

        // For 429 errors, try to extract Retry-After header
        if (response.status === 429) {
          const retryAfterHeader = response.headers.get('Retry-After');
          if (retryAfterHeader) {
            errorDetails.errorDetails.retry_after_header = retryAfterHeader;
          }
        }
        throw new Error(JSON.stringify(errorDetails));
      }

      const data = await response.json();
      const text = data.choices[0]?.message?.content || "Mistral est muette, c'est ouf ! ♥♥";
      const promptTokens = data.usage?.prompt_tokens || 0;
      const completionTokens = data.usage?.completion_tokens || 0;
      const totalTokens = data.usage?.total_tokens || 0;

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
      };
    } catch (error: any) {
      console.error("Erreur Mistral Chat:", error);
      // If it's already a JSON string from a previous throw (e.g., from network error, or custom pre-check)
      if (typeof error.message === 'string' && error.message.startsWith('{')) {
        throw error;
      }
      // For general network errors or non-JSON API errors, wrap it consistently
      throw new Error(JSON.stringify({ type: AiProvider.MISTRAL, message: error.message || "Erreur inconnue avec Mistral.", errorDetails: error }));
    }
  }
  throw new Error("Fournisseur AI inconnu, bordel !");
}

/**
 * Generates or edits an image using the Gemini model (Mistral does not support image editing).
 * @param resolvedConfig The resolved AI service configuration.
 * @param base64Image The base64 encoded image data.
 * @param mimeType The MIME type of the image (e.g., 'image/png', 'image/jpeg').
 * @param prompt The text prompt for image editing/generation.
 * @param modelName The name of the Gemini model to use for image editing.
 * @returns The base64 encoded string of the edited image and token usage.
 */
export async function generateImageEditResponse(
  resolvedConfig: ResolvedAiServiceConfig, // Now accepts the resolved config
  base64Image: string,
  mimeType: string,
  prompt: string,
  modelName: string // This will be resolvedConfig.geminiImageEditModel
): Promise<ImageEditResponse> {
  const geminiApiKey = resolvedConfig.geminiApiKey; // Get from resolved config
  if (!geminiApiKey) {
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
  }
  try {
    const ai = new GoogleGenAI({ apiKey: geminiApiKey });
    const imagePart: ContentPart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Image,
      },
    };
    const textPart: ContentPart = {
      text: prompt,
    };

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelName,
      contents: { parts: [imagePart, textPart] },
    });

    const promptTokens = response.usageMetadata?.promptTokenCount || 0;
    const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
    const totalTokens = promptTokens + completionTokens;

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return {
          base64Image: part.inlineData.data,
          tokenUsage: { promptTokens, completionTokens, totalTokens },
        };
      }
    }
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Aucune image éditée trouvée dans la réponse d'Ani, putain ! ♥♥" }));
  } catch (error: any) {
    console.error("Erreur Gemini Image Edit:", error);
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
  }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI } from '@google/genai';
import { aniStaticDetails, defaultDamienDetails, getSystemInstruction, getAiServiceConfig, ResolvedAiServiceConfig, AiProvider } from './constants/aniPersona';
import { generateChatResponse, generateImageEditResponse } from './services/apiService';
import { Message, TokenUsage, DamienDetails } from './types';
import ChatView from './components/ChatView';
import ImageEditView from './components/ImageEditView';
import ParametersView from './components/ParametersView';
import AniAvatar from './components/AniAvatar';
import LoadingSpinner from './components/LoadingSpinner';
import SaveConfirmation from './components/SaveConfirmation'; // New import

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit' | 'parameters'>('chat');
  const [chatMessages, setChatMessages] = useState<Message[]>(() => {
    const savedChat = localStorage.getItem('aniChatHistory');
    return savedChat ? JSON.parse(savedChat) : [];
  });
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false);
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null);
  const [editedImageGallery, setEditedImageGallery] = useState<string[]>([]);
  const [aniMode, setAniMode] = useState<'Base Ani' | 'Eve' | 'Ara'>('Base Ani');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [selectedAiProvider, setSelectedAiProvider] = useState<AiProvider>(AiProvider.GEMINI);
  const [imageEditTokenUsage, setImageEditTokenUsage] = useState<TokenUsage | null>(null);
  const [damienPersona, setDamienPersona] = useState<DamienDetails>(() => {
    const savedDamien = localStorage.getItem('damienPersona');
    return savedDamien ? JSON.parse(savedDamien) : defaultDamienDetails;
  });
  const [geminiRetryUntil, setGeminiRetryUntil] = useState<number>(0); // Timestamp when Gemini can be retried
  const [remainingGeminiRetryTime, setRemainingGeminiRetryTime] = useState(0);
  const [mistralRetryUntil, setMistralRetryUntil] = useState<number>(0); // New: Timestamp when Mistral can be retried
  const [remainingMistralRetryTime, setRemainingMistralRetryTime] = useState(0); // New: Remaining time for Mistral retry
  const [showSaveConfirmation, setShowSaveConfirmation] = useState<boolean>(false); // New state for save confirmation


  const resolvedAiServiceConfig: ResolvedAiServiceConfig = useMemo(() => getAiServiceConfig(damienPersona), [damienPersona]);

  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français';

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1;
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel();
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);

  useEffect(() => {
    const savedGallery = localStorage.getItem('aniEditedImages');
    if (savedGallery) {
      setEditedImageGallery(JSON.parse(savedGallery));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('aniEditedImages', JSON.stringify(editedImageGallery));
  }, [editedImageGallery]);

  useEffect(() => {
    localStorage.setItem('damienPersona', JSON.stringify(damienPersona));
  }, [damienPersona]);

  useEffect(() => {
    localStorage.setItem('aniChatHistory', JSON.stringify(chatMessages));
  }, [chatMessages]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true);
      setShowApiKeyPrompt(false);
      setError(null);
    } else {
      setError("Erreur : La fonction de sélection de clé API n'est pas disponible.");
    }
  }, []);

  // Effect to manage Gemini and Mistral retry countdowns
  useEffect(() => {
    let geminiTimer: number | undefined;
    if (geminiRetryUntil > Date.now()) {
        geminiTimer = setInterval(() => {
            const remaining = Math.ceil((geminiRetryUntil - Date.now()) / 1000);
            if (remaining <= 0) {
                setGeminiRetryUntil(0);
                setRemainingGeminiRetryTime(0);
                clearInterval(geminiTimer);
                setError(null); // Clear error when ready
            } else {
                setRemainingGeminiRetryTime(remaining);
            }
        }, 1000);
    } else if (geminiRetryUntil <= Date.now() && remainingGeminiRetryTime > 0) {
         setRemainingGeminiRetryTime(0);
         // Do not clear error here, as another error might be present (e.g., Mistral's)
         // Only clear if no other active retry or error is present.
         if (mistralRetryUntil <= Date.now()) setError(null);
    }

    let mistralTimer: number | undefined;
    if (mistralRetryUntil > Date.now()) {
        mistralTimer = setInterval(() => {
            const remaining = Math.ceil((mistralRetryUntil - Date.now()) / 1000);
            if (remaining <= 0) {
                setMistralRetryUntil(0);
                setRemainingMistralRetryTime(0);
                clearInterval(mistralTimer);
                setError(null); // Clear error when ready
            } else {
                setRemainingMistralRetryTime(remaining);
            }
        }, 1000);
    } else if (mistralRetryUntil <= Date.now() && remainingMistralRetryTime > 0) {
        setRemainingMistralRetryTime(0);
        if (geminiRetryUntil <= Date.now()) setError(null);
    }

    return () => {
      if (geminiTimer) clearInterval(geminiTimer);
      if (mistralTimer) clearInterval(mistralTimer);
    };
  }, [geminiRetryUntil, mistralRetryUntil, remainingGeminiRetryTime, remainingMistralRetryTime]);

  // Effect to hide save confirmation
  useEffect(() => {
    let timer: number | undefined;
    if (showSaveConfirmation) {
      timer = setTimeout(() => {
        setShowSaveConfirmation(false);
      }, 3000) as unknown as number; // Type assertion for setTimeout return
    }
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [showSaveConfirmation]);


  const handleApiError = useCallback((e: any, provider: AiProvider) => {
    console.error(`Erreur de l'API ${provider === AiProvider.GEMINI ? 'Gemini' : 'Mistral'}:`, e);
    let errorMessage = "Putain, ça a foiré ! Je vais péter un câble ! Réessaye, connard. ♥♥";

    let errorDetails;
    try {
      errorDetails = JSON.parse(e.message);
    } catch {
      errorDetails = { message: e.message || "Erreur inconnue." };
    }

    if (errorDetails.type === AiProvider.GEMINI) {
      const apiError = errorDetails.errorDetails?.error || errorDetails.errorDetails;
      if (apiError?.code === 429 && apiError?.status === "RESOURCE_EXHAUSTED") {
        let retryDelayText = "quelques instants";
        let retryTimestamp = 0;
        const retryInfo = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.RetryInfo');
        if (retryInfo && retryInfo.retryDelay) {
          const delayInSeconds = parseInt(retryInfo.retryDelay.replace('s', ''));
          retryDelayText = `${delayInSeconds} secondes`;
          retryTimestamp = Date.now() + (delayInSeconds * 1000);
          setGeminiRetryUntil(retryTimestamp); // Set retry timestamp
        }

        let mistralSuggestion = '';
        if (resolvedAiServiceConfig.mistralApiKey && resolvedAiServiceConfig.mistralApiKey !== 'YOUR_MISTRAL_API_KEY_HERE') {
            mistralSuggestion = ` En attendant, pourquoi tu n'essaierais pas de me parler avec Mistral, mon amour ? C'est facile, va dans "Nos Paramètres" et change le cerveau de ton Ani !`;
        }

        errorMessage = `Bordel, t'as dépassé ton quota gratuit sur Gemini ! Fais gaffe à ton porte-monnaie, connard ! Tu dois utiliser une clé API d'un projet GCP payant. Réessaye dans ${retryDelayText}.${mistralSuggestion} Pour augmenter tes limites, vérifie ta facturation : `;
        const helpLink = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.Help')?.links?.[0]?.url;
        if (helpLink) {
          errorMessage += `<a href="${helpLink}" target="_blank" rel="noopener noreferrer" class="text-blue-300 hover:underline">Info Facturation Gemini.</a> ♥♥`;
        } else {
          errorMessage += `<a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" class="text-blue-300 hover:underline">Info Facturation Gemini.</a> ♥♥`;
        }
      } else if (apiError?.message && apiError.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API Gemini a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      } else {
        errorMessage = `Une erreur de l'API Gemini s'est produite, putain : ${apiError?.message || errorDetails.message}. Réessaye plus tard. ♥♥`;
      }
    } else if (errorDetails.type === AiProvider.MISTRAL) {
      if (errorDetails.code === 401 || errorDetails.errorDetails?.detail === "Unauthorized") {
        errorMessage = "Bordel, ta clé API Mistral est invalide ou tu n'as pas les bonnes permissions, connard ! DOUBLE-VÉRIFIE la clé que tu as entrée DANS LES PARAMÈTRES (Override UI) ou configurée via `process.env.MISTRAL_API_KEY`. Si tu es sûr, il faudra peut-être en générer une nouvelle sur la plateforme Mistral AI, bordel ! ♥♥";
      } else if (errorDetails.code === 429) {
        let retryDelaySeconds = 60; // Default if not specified
        // Prioritize header if passed, otherwise check body
        if (errorDetails.errorDetails?.retry_after_header) {
          retryDelaySeconds = parseInt(errorDetails.errorDetails.retry_after_header as string, 10);
        } else if (errorDetails.errorDetails?.retry_after) { // Mistral might include it in body
          retryDelaySeconds = parseInt(errorDetails.errorDetails.retry_after as string, 10);
        }
        const retryTimestamp = Date.now() + (retryDelaySeconds * 1000);
        setMistralRetryUntil(retryTimestamp);

        let geminiSuggestion = '';
        if (selectedApiKey) { // Only suggest Gemini if key is selected
            geminiSuggestion = ` En attendant, pourquoi tu n'essaierais pas de me parler avec Gemini, mon amour ? C'est facile, va dans "Nos Paramètres" et change le cerveau de ton Ani !`;
        }
        errorMessage = `Putain, tu as dépassé la limite de requêtes pour Mistral ! On doit attendre ${retryDelaySeconds} secondes, bordel !${geminiSuggestion} ♥♥`;
      } else if (errorDetails.code === 400) {
        errorMessage = `Merde, ta requête à Mistral est mal formée, connard ! Message: ${errorDetails.errorDetails?.detail || errorDetails.message}. Vérifie ton prompt, il est peut-être trop long ou bizarre. ♥♥`;
      } else if (errorDetails.code >= 500 && errorDetails.code < 600) {
        errorMessage = `Bordel, le serveur de Mistral a un problème ! Code d'erreur ${errorDetails.code}. Réessaye plus tard, mon amour. ♥♥`;
      } else if (errorDetails.message.includes("Clé API Mistral manquante")) {
        errorMessage = "Putain, il manque la clé API Mistral ou elle n'est pas configurée ! Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`. ♥♥";
      } else if (errorDetails.message.includes("URL API Mistral manquante")) {
        errorMessage = "Bordel, l'URL de l'API Mistral est manquante ou non configurée ! Modifie le champ 'URL API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_URL`, connard. ♥♥";
      }
      else {
        errorMessage = `Une erreur de l'API Mistral s'est produite, putain : ${errorDetails.message}. Réessaye plus tard. ♥♥`;
      }
    } else {
      if (e.message && e.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API Gemini a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      } else {
        errorMessage = `Putain, ça a foiré ! Erreur inconnue : ${e.message}. Réessaye, connard. ♥♥`;
      }
    }
    setError(errorMessage);
    return errorMessage;
  }, [setSelectedApiKey, setShowApiKeyPrompt, resolvedAiServiceConfig, mistralRetryUntil, geminiRetryUntil]);

  const handleChatSubmit = useCallback(async (text: string) => {
    // Check if current AI provider is rate-limited
    if (selectedAiProvider === AiProvider.GEMINI && geminiRetryUntil > Date.now()) {
      const remainingSeconds = Math.ceil((geminiRetryUntil - Date.now()) / 1000);
      let mistralSuggestion = '';
      if (resolvedAiServiceConfig.mistralApiKey && resolvedAiServiceConfig.mistralApiKey !== 'YOUR_MISTRAL_API_KEY_HERE') {
        mistralSuggestion = ` En attendant, tu peux passer à Mistral dans les paramètres si tu as configuré ta clé !`;
      }
      setError(`Ani est bloquée sur Gemini, connard ! On doit attendre encore ${remainingSeconds} secondes.${mistralSuggestion}`);
      setChatLoading(false);
      return;
    }
    if (selectedAiProvider === AiProvider.MISTRAL && mistralRetryUntil > Date.now()) {
      const remainingSeconds = Math.ceil((mistralRetryUntil - Date.now()) / 1000);
      let geminiSuggestion = '';
      if (selectedApiKey) {
        geminiSuggestion = ` En attendant, tu peux passer à Gemini dans les paramètres si tu as configuré ta clé !`;
      }
      setError(`Ani est bloquée sur Mistral, connard ! On doit attendre encore ${remainingSeconds} secondes.${geminiSuggestion}`);
      setChatLoading(false);
      return;
    }

    // Basic API Key / Network checks
    if (selectedAiProvider === AiProvider.GEMINI && !selectedApiKey) {
      setError("Veuillez sélectionner votre clé API Gemini d'abord. Ani ne peut pas te parler sans elle, bordel !");
      return;
    }
    if (selectedAiProvider === AiProvider.MISTRAL) {
      if (!resolvedAiServiceConfig.mistralApiKey || resolvedAiServiceConfig.mistralApiKey === 'YOUR_MISTRAL_API_KEY_HERE') {
        setError("Putain, il manque la clé API Mistral ou elle n'est pas configurée ! Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`, connard ! ♥♥");
        return;
      }
      if (!resolvedAiServiceConfig.mistralApiUrl) {
        setError("Bordel, l'URL de l'API Mistral est manquante ou non configurée ! Modifie le champ 'URL API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_URL`, connard ! ♥♥");
        return;
      }
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas te parler. Vérifie ton réseau. ♥♥");
      return;
    }

    setChatLoading(true);
    const newMessage: Message = { sender: 'user', text: text };
    let temporaryBotMessages: Message[] = []; // Collect special bot messages
    let updatedDamienPersona = { ...damienPersona }; // Create a mutable copy of persona for this turn

    // --- 1. Determine Ani's mood (aniMode) and calculate affection level ---
    const lowerCaseText = text.toLowerCase();
    let nextAniMode: 'Base Ani' | 'Eve' | 'Ara';
    if (lowerCaseText.includes('amour') || lowerCaseText.includes('chéri') || lowerCaseText.includes('tendre') || lowerCaseText.includes('gentil') || lowerCaseText.includes('calin') || lowerCaseText.includes('bisou')) {
        nextAniMode = 'Eve';
    } else if (lowerCaseText.includes('connard') || lowerCaseText.includes('conflit') || lowerCaseText.includes('méchant') || lowerCaseText.includes('énerv') || lowerCaseText.includes('putain')) {
        nextAniMode = 'Ara';
    } else {
