    onUpdateDamienDetails({
      ...damienDetails,
      isSexyModeEnabled: newSexyModeState,
      // If toggling manually, reset auto-consent to require it again if manually disabled
      // and re-enabled, or just keep it true if it was already given.
      // For simplicity, if manually toggled, auto-consent stays as it was.
    });
  };

  // Define placeholders and default values for comparison
  const MISTRAL_API_KEY_PLACEHOLDER = 'YOUR_MISTRAL_API_KEY_HERE';
  // Corrected default URL to match the one used in getAiServiceConfig
  const MISTRAL_API_URL_DEFAULT = 'https://api.mistral.ai/v1/chat/completions';

  // Determine if Mistral API Key is configured (not empty and not the placeholder)
  const mistralApiKeyConfigured = resolvedMistralApiKey !== '' && resolvedMistralApiKey !== MISTRAL_API_KEY_PLACEHOLDER;

  // Determine if Mistral API URL is configured (not empty). The default URL is functional.
  const mistralApiUrlConfigured = resolvedMistralApiUrl !== '';

  // Helper to determine the source of the Mistral API key
  const getMistralApiKeySource = () => {
      const overrideVal = damienDetails.mistralApiKeyOverride?.trim();
      const envVal = process.env.MISTRAL_API_KEY?.trim();

      if (overrideVal && overrideVal !== MISTRAL_API_KEY_PLACEHOLDER) {
          return 'Override UI';
      }
      // Check if environment variable is set and not the placeholder
      if (envVal && envVal !== MISTRAL_API_KEY_PLACEHOLDER) {
          return 'Environnement';
      }
      // If resolved config is not the placeholder, it must come from a valid default in code
      if (resolvedMistralApiKey !== MISTRAL_API_KEY_PLACEHOLDER) { // Check the resolved value, which includes the default from constants/aniPersona.ts
          return 'Défaut (code)';
      }
      return 'Non configurée';
  };

  // Helper to determine the source of the Mistral API URL
  const getMistralApiUrlSource = () => {
      const overrideVal = damienDetails.mistralApiUrlOverride?.trim();
      const envVal = process.env.MISTRAL_API_URL?.trim();

      if (overrideVal && overrideVal !== '') {
          return 'Override UI';
      }
      if (envVal && envVal !== '') {
          return 'Environnement';
