import React from 'react';
import { AniDetails, DamienDetails, AniCustomization } from '../types';
import AniAvatar from './AniAvatar';
import { AiProvider } from '../constants/aniPersona';

interface ParametersViewProps {
  aniDetails: AniDetails;
  damienDetails: DamienDetails;
  onUpdateDamienDetails: (details: DamienDetails) => void;
  onResetDamienDetails: () => void;
  selectedAiProvider: AiProvider;
  onSelectAiProvider: (provider: AiProvider) => void;
  selectedGeminiApiKey: boolean;
  onOpenGeminiKeySelection: () => void;
  resolvedMistralApiKey: string;
  resolvedMistralApiUrl: string;
  onClearMistralOverrides: () => void;
  geminiTotalTokensUsed: number; // New: Total Gemini tokens used
  mistralTotalTokensUsed: number; // New: Total Mistral tokens used
  onResetTokenUsage: () => void; // New: Function to reset token usage
}

const ParametersView: React.FC<ParametersViewProps> = ({
  aniDetails,
  damienDetails,
  onUpdateDamienDetails,
  onResetDamienDetails,
  selectedAiProvider,
  onSelectAiProvider,
  selectedGeminiApiKey,
  onOpenGeminiKeySelection,
  resolvedMistralApiKey,
  resolvedMistralApiUrl,
  onClearMistralOverrides,
  geminiTotalTokensUsed, // Destructure new prop
  mistralTotalTokensUsed, // Destructure new prop
  onResetTokenUsage, // Destructure new prop
}) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type, checked } = e.target;
    onUpdateDamienDetails({
      ...damienDetails,
      [name]: type === 'checkbox' ? checked : value,
    });
  };

  const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    const numValue = Number(value);
    onUpdateDamienDetails({
      ...damienDetails,
      [name]: isNaN(numValue) ? 0 : numValue, // Ensure it's a number, default to 0
    });
  };

  const handleAniCustomizationChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const { name, value } = e.target;
    onUpdateDamienDetails({
      ...damienDetails,
      aniCustomization: {
        ...damienDetails.aniCustomization,
        [name]: value as keyof AniCustomization,
      },
    });
  };

  const handleSexyModeToggle = () => {
    const newSexyModeState = !damienDetails.isSexyModeEnabled;
    if (newSexyModeState) {
      const confirmToggle = window.confirm(
        "ATTENTION, CONNARD ! En activant le 'Mode Sexy 18+', Ani deviendra TRÈS suggestive, intime et coquine. Le contenu pourrait être explicite et ne convient pas à tous les publics. Es-tu sûr de vouloir continuer, mon amour ?"
      );
      if (!confirmToggle) {
        return; // User cancelled
      }
    }
    onUpdateDamienDetails({
      ...damienDetails,
      isSexyModeEnabled: newSexyModeState,
      // If toggling manually, reset auto-consent to require it again if manually disabled
      // and re-enabled, or just keep it true if it was already given.
      // For simplicity, if manually toggled, auto-consent stays as it was.
    });
  };

  const handleTelegramAutoResponseToggle = () => {
    const newAutoResponseState = !damienDetails.enableTelegramAutoResponse;
    if (newAutoResponseState) {
      const confirmToggle = window.confirm(
        "ATTENTION, CONNARD ! Activer la réponse automatique Ani sur Telegram nécessitera un SERVICE BACKEND (un serveur) pour fonctionner réellement et en toute sécurité. Sans ça, Ani ne pourra pas répondre automatiquement aux messages entrants. Es-tu sûr de vouloir activer cette option de configuration ?"
      );
      if (!confirmToggle) {
        return; // User cancelled
      }
    }
    onUpdateDamienDetails({
      ...damienDetails,
      enableTelegramAutoResponse: newAutoResponseState,
    });
  };

  // Define placeholders and default values for comparison
  const MISTRAL_API_KEY_PLACEHOLDER = 'YOUR_MISTRAL_API_KEY_HERE';
  // Corrected default URL to match the one used in getAiServiceConfig
  const MISTRAL_API_URL_DEFAULT = 'https://api.mistral.ai/v1/chat/completions';

  // Determine if Mistral API Key is configured (not empty and not the placeholder)
  const mistralApiKeyConfigured = resolvedMistralApiKey !== '' && resolvedMistralApiKey !== MISTRAL_API_KEY_PLACEHOLDER;

  // Determine if Mistral API URL is configured (not empty). The default URL is functional.
  const mistralApiUrlConfigured = resolvedMistralApiUrl !== '';

  // Helper to determine the source of the Mistral API key
  const getMistralApiKeySource = () => {
      const overrideVal = damienDetails.mistralApiKeyOverride?.trim();
      const envVal = process.env.MISTRAL_API_KEY?.trim();

      if (overrideVal && overrideVal !== MISTRAL_API_KEY_PLACEHOLDER) {
          return 'Override UI';
      }
      // Check if environment variable is set and not the placeholder
      if (envVal && envVal !== MISTRAL_API_KEY_PLACEHOLDER) {
          return 'Environnement';
      }
      // If resolved config is not the placeholder, it must come from a valid default in code
      if (resolvedMistralApiKey !== MISTRAL_API_KEY_PLACEHOLDER) { // Check the resolved value, which includes the default from constants/aniPersona.ts
          return 'Défaut (code)';
      }
      return 'Non configurée';
  };

