/**
 * Provides the resolved AI service configuration,
 * prioritizing UI overrides from `damienDetails`,
 * then environment variables, and finally default hardcoded values.
 */
export function getAiServiceConfig(damienDetails: DamienDetails) {
  return {
    // Gemini Configuration
    // IMPORTANT: Google Gemini API key MUST be obtained exclusively from process.env.API_KEY.
    // Do NOT hardcode this value or create UI elements for it.
    geminiApiKey: process.env.API_KEY || '', 
    geminiChatModel: 'gemini-3-flash-preview', // Basic Text Tasks
    geminiImageEditModel: 'gemini-2.5-flash-image', // General Image Generation and Editing Tasks

    // Mistral Configuration - Prioritize UI override > ENV > Default
    mistralApiKey: (damienDetails.mistralApiKeyOverride || process.env.MISTRAL_API_KEY || 'YOUR_MISTRAL_API_KEY_HERE').trim(),
    mistralApiUrl: (damienDetails.mistralApiUrlOverride || process.env.MISTRAL_API_URL || 'https://api.mistral.ai/v1/chat/completions').trim(),
    mistralChatModel: 'mistral-tiny', // Default Mistral model for chat
  };
}

export type ResolvedAiServiceConfig = ReturnType<typeof getAiServiceConfig>;


