import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { ContentPart, TokenUsage } from '../types';
import { AiProvider, getAiServiceConfig, ResolvedAiServiceConfig, CHAT_MAX_OUTPUT_TOKENS, GEMINI_THINKING_BUDGET, MISTRAL_MAX_TOKENS_DIRECT } from '../constants/aniPersona'; // Updated import to use getAiServiceConfig and ResolvedAiServiceConfig

interface ChatResponse {
  text: string;
  tokenUsage: TokenUsage;
}

interface ImageEditResponse {
  base64Image: string;
  tokenUsage: TokenUsage;
}

/**
 * Generates a chat response from the selected AI model (Gemini or Mistral).
 * @param provider The selected AI provider.
 * @param resolvedConfig The resolved AI service configuration.
 * @param prompt The user's message.
 * @param systemInstruction The system instruction for the chat.
 * @param modelName The name of the AI model to use for chat.
 * @returns The text response and token usage.
 */
export async function generateChatResponse(
  provider: AiProvider,
  resolvedConfig: ResolvedAiServiceConfig, // Now accepts the resolved config
  prompt: string,
  systemInstruction: string,
  modelName: string
): Promise<ChatResponse> {
  if (provider === AiProvider.GEMINI) {
    const geminiApiKey = resolvedConfig.geminiApiKey; // Get from resolved config
    if (!geminiApiKey) {
      // This case should ideally be caught by App.tsx's API key selection check
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
    }
    try {
      const ai = new GoogleGenAI({ apiKey: geminiApiKey });
      const chat = ai.chats.create({
        model: modelName, // This will be resolvedConfig.geminiChatModel
        config: {
          systemInstruction: systemInstruction,
          maxOutputTokens: CHAT_MAX_OUTPUT_TOKENS, // Enforce shorter responses
          thinkingConfig: { thinkingBudget: GEMINI_THINKING_BUDGET }, // Reserve tokens for thinking
        },
      });

      const response: GenerateContentResponse = await chat.sendMessage({ message: prompt });
      const text = response.text || "Ani est muette, c'est ouf ! ♥♥";
      const promptTokens = response.usageMetadata?.promptTokenCount || 0;
      const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
      const totalTokens = promptTokens + completionTokens;

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
      };
    } catch (error: any) {
      console.error("Erreur Gemini Chat:", error);
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
    }
  } else if (provider === AiProvider.MISTRAL) {
    const mistralApiKey = resolvedConfig.mistralApiKey; // Get from resolved config
    const mistralApiUrl = resolvedConfig.mistralApiUrl; // Get from resolved config

    if (!mistralApiKey || mistralApiKey === 'YOUR_MISTRAL_API_KEY_HERE') {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "Clé API Mistral manquante ou non configurée. Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`, bordel !",
        code: 401
      }));
    }
    if (!mistralApiUrl) {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "URL API Mistral manquante ou non configurée. Modifie le champ 'URL API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_URL`, connard !",
        code: 400 // Assuming 400 for bad URL config, or custom code
      }));
    }

    try {
      const response = await fetch(mistralApiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${mistralApiKey}`,
        },
        body: JSON.stringify({
          model: modelName, // This will be resolvedConfig.mistralChatModel
          messages: [{ role: 'user', content: systemInstruction ? `${systemInstruction}\n${prompt}` : prompt }],
          max_tokens: MISTRAL_MAX_TOKENS_DIRECT, // Enforce shorter responses for Mistral
          // Mistral doesn't have a direct 'systemInstruction' in the /chat/completions endpoint
          // For now, prepending to the user prompt if systemInstruction exists.
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        const errorDetails: any = { type: AiProvider.MISTRAL, message: errorData.message || response.statusText, code: response.status, errorDetails: errorData };

        // For 429 errors, try to extract Retry-After header
        if (response.status === 429) {
          const retryAfterHeader = response.headers.get('Retry-After');
          if (retryAfterHeader) {
            errorDetails.errorDetails.retry_after_header = retryAfterHeader;
          }
        }
        throw new Error(JSON.stringify(errorDetails));
      }

      const data = await response.json();
      const text = data.choices[0]?.message?.content || "Mistral est muette, c'est ouf ! ♥♥";
      const promptTokens = data.usage?.prompt_tokens || 0;
      const completionTokens = data.usage?.completion_tokens || 0;
      const totalTokens = data.usage?.total_tokens || 0;

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
      };
    } catch (error: any) {
      console.error("Erreur Mistral Chat:", error);
      // If it's already a JSON string from a previous throw (e.g., from network error, or custom pre-check)
      if (typeof error.message === 'string' && error.message.startsWith('{')) {
        throw error;
      }
      // For general network errors or non-JSON API errors, wrap it consistently
      throw new Error(JSON.stringify({ type: AiProvider.MISTRAL, message: error.message || "Erreur inconnue avec Mistral.", errorDetails: error }));
    }
  }
  throw new Error("Fournisseur AI inconnu, bordel !");
}

/**
 * Generates or edits an image using the Gemini model (Mistral does not support image editing).
 * @param resolvedConfig The resolved AI service configuration.
 * @param base64Image The base64 encoded image data.
 * @param mimeType The MIME type of the image (e.g., 'image/png', 'image/jpeg').
 * @param prompt The text prompt for image editing/generation.
 * @param modelName The name of the Gemini model to use for image editing.
 * @returns The base64 encoded string of the edited image and token usage.
 */
export async function generateImageEditResponse(
  resolvedConfig: ResolvedAiServiceConfig, // Now accepts the resolved config
  base64Image: string,
  mimeType: string,
  prompt: string,
  modelName: string // This will be resolvedConfig.geminiImageEditModel
): Promise<ImageEditResponse> {
  const geminiApiKey = resolvedConfig.geminiApiKey; // Get from resolved config
  if (!geminiApiKey) {
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
  }
  try {
    const ai = new GoogleGenAI({ apiKey: geminiApiKey });
    const imagePart: ContentPart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Image,
      },
    };
    const textPart: ContentPart = {
      text: prompt,
    };

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelName,
      contents: { parts: [imagePart, textPart] },
    });

    const promptTokens = response.usageMetadata?.promptTokenCount || 0;
    const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
    const totalTokens = promptTokens + completionTokens;

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return {
          base64Image: part.inlineData.data,
          tokenUsage: { promptTokens, completionTokens, totalTokens },
        };
      }
    }
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Aucune image éditée trouvée dans la réponse d'Ani, putain ! ♥♥" }));
  } catch (error: any) {
    console.error("Erreur Gemini Image Edit:", error);
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
  }
}

