            temporaryBotMessages.push({ sender: 'bot', text: "Je n'ai pas compris ta réponse, mon chéri. Si tu veux re-discuter du Mode Sexy 18+, dis-le moi. Continuons notre conversation pour l'instant..." });
            shouldCallAI = true;
        }
    }

