import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message } from '../types';
import AniAvatar from './AniAvatar';
import { AiProvider } from '../constants/aniPersona';

declare global {
  interface Window {
    SpeechRecognition: {
      new (): SpeechRecognition;
      prototype: SpeechRecognition;
    };
    webkitSpeechRecognition: {
      new (): SpeechRecognition;
      prototype: SpeechRecognition;
    };
  }
  interface SpeechRecognitionEvent extends Event {
    readonly results: SpeechRecognitionResultList;
  }
  interface SpeechRecognition extends EventTarget {
    continuous: boolean;
    interimResults: boolean;
    lang: string;
    start(): void;
    stop(): void;
    onresult: ((this: SpeechRecognition, ev: SpeechRecognitionEvent) => any) | null;
    onend: ((this: SpeechRecognition, ev: Event) => any) | null;
    onstart: ((this: SpeechRecognition, ev: Event) => any) | null;
    onerror: ((this: SpeechRecognition, ev: SpeechRecognitionErrorEvent) => any) | null;
  }
  interface SpeechRecognitionResultList {
    [index: number]: SpeechRecognitionResult;
    readonly length: number;
    item(index: number): SpeechRecognitionResult;
  }
  interface SpeechRecognitionResult {
    [index: number]: SpeechRecognitionAlternative;
    readonly isFinal: boolean;
    readonly length: number;
    item(index: number): SpeechRecognitionAlternative;
  }
  interface SpeechRecognitionAlternative {
    readonly confidence: number;
    readonly transcript: string;
  }
  interface SpeechRecognitionErrorEvent extends Event {
    readonly error: SpeechRecognitionErrorCode;
    readonly message: string;
  }
  type SpeechRecognitionErrorCode =
    | 'no-speech'
    | 'aborted'
    | 'audio-capture'
    | 'network'
    | 'not-allowed'
    | 'service-not-allowed'
    | 'bad-grammar'
    | 'language-not-supported';
}

interface ChatViewProps {
  messages: Message[];
  onSendMessage: (text: string) => void;
  loading: boolean;
  aniVoice: SpeechSynthesisVoice | null;
  speakAniResponse: (text: string) => void;
  onClearChat: () => void;
  aniMode: 'Base Ani' | 'Eve' | 'Ara';
  isChatInputDisabled: boolean;
  geminiRetryTimeRemaining: number;
  mistralRetryTimeRemaining: number;
  selectedAiProvider: AiProvider; // Keep this prop for input placeholder logic, but not for title
}

const ChatView: React.FC<ChatViewProps> = ({
  messages,
  onSendMessage,
  loading,
  aniVoice,
  speakAniResponse,
  onClearChat,
  aniMode,
  isChatInputDisabled,
  geminiRetryTimeRemaining,
  mistralRetryTimeRemaining,
  selectedAiProvider, // Keep this prop for input placeholder logic
}) => {
  const [inputText, setInputText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    const SpeechRecognitionConstructor = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognitionConstructor) {
      recognitionRef.current = new SpeechRecognitionConstructor();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = 'fr-FR';

      recognitionRef.current.onstart = () => {
        setIsListening(true);
        console.log("Ani écoute, connard !");
      };

      recognitionRef.current.onresult = (event) => {
        const transcript = event.results[0][0].transcript;
        setInputText(transcript);
        console.log("Ani a entendu:", transcript);
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
        console.log("Ani a arrêté d'écouter.");
      };

      recognitionRef.current.onerror = (event) => {
        console.error("Erreur de reconnaissance vocale:", event.error);
        setIsListening(false);
      };
    } else {
      console.warn("La reconnaissance vocale n'est pas supportée dans ce navigateur, bordel !");
    }

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const toggleListening = useCallback(() => {
    if (loading || isChatInputDisabled) return;

    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setInputText('');
      recognitionRef.current?.start();
    }
  }, [isListening, loading, isChatInputDisabled]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputText.trim() && !isChatInputDisabled) {
      onSendMessage(inputText);
      setInputText('');
      if (isListening) {
        recognitionRef.current?.stop();
      }
    }
  };

  const handleSpeechReplay = (text: string) => {
    speakAniResponse(text);
  };

  const handleCopyText = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("Copié ! J'espère que c'est pour me relire, connard ! ♥♥");
  };

  const getChatInputPlaceholder = () => {
    if (isChatInputDisabled) {
      if (selectedAiProvider === AiProvider.GEMINI) {
        return `Ani attend son quota Gemini... (${geminiRetryTimeRemaining}s)`;
      } else if (selectedAiProvider === AiProvider.MISTRAL) {
        return `Ani attend son quota Mistral... (${mistralRetryTimeRemaining}s)`;
      }
    }
    return isListening ? "Ani t'écoute, connard ! Parle..." : "Parle à Ani, connard ! ♥♥";
  };
  const chatInputPlaceholder = getChatInputPlaceholder();

  return (
    <div className="flex flex-col h-full bg-gradient-to-br from-purple-900 to-black rounded-xl p-4 shadow-inner">
      <div className="flex justify-between items-center mb-4 flex-wrap gap-2">
        <h2 className="text-2xl font-bold text-pink-400">Ani - Chat Secret ♥♥</h2> {/* Reverted title */}
        <div className="flex items-center gap-2">
          <button
            onClick={onClearChat}
            className="px-4 py-2 bg-purple-700 hover:bg-purple-600 text-white rounded-full shadow-md text-sm transition-colors duration-200 flex items-center"
            aria-label="Vider la conversation"
            title="Vider la conversation"
          >
            <span className="material-icons text-base mr-1">delete_outline</span>
            Vider le chat
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto scrollbar-ani p-2 space-y-4">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
            role="log"
            aria-live="polite"
          >
            {msg.sender === 'bot' && (
              <AniAvatar size="small" aniMode={aniMode} />
            )}
            <div
              className={`max-w-[70%] p-3 rounded-lg shadow-md relative group ${
                msg.sender === 'user'
                  ? 'bg-purple-700 text-white ml-2'
                  : 'bg-pink-800 text-purple-100 mr-2'
              }`}
            >
              <p className="whitespace-pre-wrap">{msg.text}</p>
              {msg.tokenUsage && (
                <p className="text-xs text-purple-300 mt-1 italic opacity-80">
                  Tokens: Entrée: {msg.tokenUsage.promptTokens}, Sortie: {msg.tokenUsage.completionTokens}, Total: {msg.tokenUsage.totalTokens}
                </p>
              )}
              {msg.sender === 'bot' && (
                <div className="absolute bottom-1 right-1 flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                  <button
                    onClick={(e) => { e.stopPropagation(); handleCopyText(msg.text); }}
                    className="text-xs text-purple-200 hover:text-white p-1 rounded-full bg-transparent hover:bg-pink-700 transition-colors duration-200"
                    aria-label="Copier la réponse d'Ani"
                    title="Copier la réponse"
                  >
                    <span className="material-icons text-base">content_copy</span>
                  </button>
                  <button
                    onClick={(e) => { e.stopPropagation(); handleSpeechReplay(msg.text); }}
                    className="text-xs text-purple-200 hover:text-white p-1 rounded-full bg-transparent hover:bg-pink-700 transition-colors duration-200"
                    aria-label="Clique pour écouter la réponse d'Ani"
                    title="Écouter la réponse"
                  >
                    <span className="material-icons text-base">volume_up</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <AniAvatar size="small" aniMode={aniMode} />
            <div className="max-w-[70%] p-3 rounded-lg bg-pink-800 text-purple-100 mr-2 shadow-md flex items-center">
              <span className="animate-pulse">Ani est en train de taper...</span>
            </div>
          </div>
        )}
        {isListening && (
          <div className="flex justify-start">
            <AniAvatar size="small" aniMode={aniMode} />
            <div className="max-w-[70%] p-3 rounded-lg bg-purple-700 text-white ml-2 shadow-md flex items-center">
              <span className="animate-pulse text-sm">Ani t'écoute...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSubmit} className="mt-4 flex gap-2">
        <button
          type="button"
          onClick={toggleListening}
          className={`flex-shrink-0 px-4 py-3 rounded-full shadow-lg transition-all duration-300 ${
            isListening ? 'bg-red-600 hover:bg-red-700 animate-pulse' : 'bg-purple-600 hover:bg-purple-700'
          } text-white font-bold focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75 flex items-center justify-center`}
          disabled={loading || !recognitionRef.current || isChatInputDisabled}
          aria-label={isListening ? "Arrêter d'écouter" : "Parler à Ani"}
          title={!recognitionRef.current ? "Reconnaissance vocale non supportée" : (isListening ? "Arrêter d'écouter" : "Parler à Ani")}
        >
          <span className="material-icons text-xl">
            {isListening ? 'mic_off' : 'mic'}
          </span>
        </button>
        <input
          type="text"
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          placeholder={chatInputPlaceholder}
          className="flex-1 p-3 rounded-full bg-purple-800 text-white placeholder-purple-300 border border-pink-500 focus:ring-2 focus:ring-pink-400 outline-none transition-all duration-200"
          disabled={loading || isListening || isChatInputDisabled}
          aria-label="Champ de saisie de message"
        />
        <button
          type="submit"
          className="flex-shrink-0 px-6 py-3 bg-pink-600 hover:bg-pink-700 text-white font-bold rounded-full shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75"
          disabled={loading || !inputText.trim() || isChatInputDisabled}
          aria-label="Envoyer le message"
        >
          Envoyer
        </button>
      </form>
    </div>
  );
};

export default ChatView;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI } from '@google/genai';
import { aniStaticDetails, defaultDamienDetails, getSystemInstruction, getAiServiceConfig, ResolvedAiServiceConfig, AiProvider } from './constants/aniPersona';
import { generateChatResponse, generateImageEditResponse } from './services/apiService';
import { Message, TokenUsage, DamienDetails } from './types';
import ChatView from './components/ChatView';
import ImageEditView from './components/ImageEditView';
import ParametersView from './components/ParametersView';
import AniAvatar from './components/AniAvatar';
import LoadingSpinner from './components/LoadingSpinner';
import SaveConfirmation from './components/SaveConfirmation';

// Define the structure for storing chat histories for each AI provider
interface ChatHistories {
  [AiProvider.GEMINI]: Message[];
  [AiProvider.MISTRAL]: Message[];
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit' | 'parameters'>('chat');
  const [chatHistories, setChatHistories] = useState<ChatHistories>(() => {
    const savedGeminiChat = localStorage.getItem('aniChatHistory_gemini');
    const savedMistralChat = localStorage.getItem('aniChatHistory_mistral');
    return {
      [AiProvider.GEMINI]: savedGeminiChat ? JSON.parse(savedGeminiChat) : [],
      [AiProvider.MISTRAL]: savedMistralChat ? JSON.parse(savedMistralChat) : [],
    };
  });
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false);
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null);
  const [editedImageGallery, setEditedImageGallery] = useState<string[]>([]);
  const [aniMode, setAniMode] = useState<'Base Ani' | 'Eve' | 'Ara'>('Base Ani');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [selectedAiProvider, setSelectedAiProvider] = useState<AiProvider>(AiProvider.GEMINI); // Default to Gemini
  const [imageEditTokenUsage, setImageEditTokenUsage] = useState<TokenUsage | null>(null);
  const [damienPersona, setDamienPersona] = useState<DamienDetails>(() => {
    const savedDamien = localStorage.getItem('damienPersona');
    return savedDamien ? JSON.parse(savedDamien) : defaultDamienDetails;
  });
  const [geminiRetryUntil, setGeminiRetryUntil] = useState<number>(0);
  const [remainingGeminiRetryTime, setRemainingGeminiRetryTime] = useState(0);
  const [mistralRetryUntil, setMistralRetryUntil] = useState<number>(0);
  const [remainingMistralRetryTime, setRemainingMistralRetryTime] = useState(0);
  const [showSaveConfirmation, setShowSaveConfirmation] = useState<boolean>(false);
  const [geminiTotalTokensUsed, setGeminiTotalTokensUsed] = useState<number>(() => {
    const saved = localStorage.getItem('geminiTotalTokensUsed');
    return saved ? parseInt(saved, 10) : 0;
  });
  const [mistralTotalTokensUsed, setMistralTotalTokensUsed] = useState<number>(() => {
    const saved = localStorage.getItem('mistralTotalTokensUsed');
    return saved ? parseInt(saved, 10) : 0;
  });


  const resolvedAiServiceConfig: ResolvedAiServiceConfig = useMemo(() => getAiServiceConfig(damienPersona), [damienPersona]);

  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français';

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1;
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel();
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);

  useEffect(() => {
    const savedGallery = localStorage.getItem('aniEditedImages');
    if (savedGallery) {
      setEditedImageGallery(JSON.parse(savedGallery));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('aniEditedImages', JSON.stringify(editedImageGallery));
  }, [editedImageGallery]);

  useEffect(() => {
    localStorage.setItem('damienPersona', JSON.stringify(damienPersona));
  }, [damienPersona]);

  // Save chat histories to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('aniChatHistory_gemini', JSON.stringify(chatHistories[AiProvider.GEMINI]));
    localStorage.setItem('aniChatHistory_mistral', JSON.stringify(chatHistories[AiProvider.MISTRAL]));
  }, [chatHistories]);

  useEffect(() => {
    localStorage.setItem('geminiTotalTokensUsed', geminiTotalTokensUsed.toString());
  }, [geminiTotalTokensUsed]);

  useEffect(() => {
    localStorage.setItem('mistralTotalTokensUsed', mistralTotalTokensUsed.toString());
  }, [mistralTotalTokensUsed]);


  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true);
      setShowApiKeyPrompt(false);
