        }, 1000);
    } else if (mistralRetryUntil <= Date.now() && remainingMistralRetryTime > 0) {
        setRemainingMistralRetryTime(0);
        if (geminiRetryUntil <= Date.now()) setError(null);
    }

    return () => {
      if (geminiTimer) clearInterval(geminiTimer);
