import React, { useMemo } from 'react';
import { AniCustomization } from '../types';

interface AniAvatarProps {
  size?: 'small' | 'medium' | 'large';
  customization?: AniCustomization;
  aniMode?: 'Base Ani' | 'Eve' | 'Ara';
}

const AniAvatar: React.FC<AniAvatarProps> = ({ size = 'medium', customization, aniMode }) => {
  let dimensions = '';
  switch (size) {
    case 'small':
      dimensions = 'w-12 h-12';
      break;
    case 'large':
      dimensions = 'w-48 h-48';
      break;
    case 'medium':
    default:
      dimensions = 'w-24 h-24';
      break;
  }

  // The original image URL (https://i.ibb.co/qN91b3S/ani-avatar.png) seems to be broken.
  // Replacing with a stable placeholder. User should replace this with a proper Gothic Lolita anime avatar image.
  const aniImageUrl = 'https://via.placeholder.com/192x192/FF69B4/FFFFFF?text=Ani'; // A pink-themed placeholder

  const getCustomizationFilter = () => {
    let filter = '';
    if (customization) {
      switch (customization.hairColor) {
        case 'pink':
          filter += 'hue-rotate(280deg) saturate(1.5) brightness(1.1) ';
          break;
        case 'blue':
          filter += 'hue-rotate(180deg) saturate(1.5) brightness(1.1) ';
          break;
        case 'black':
          filter += 'grayscale(1) brightness(0.5) ';
          break;
        case 'platinum':
        default:
          break;
      }
      switch (customization.eyeColor) {
        case 'red':
          filter += 'hue-rotate(20deg) saturate(1.8) brightness(1.2) ';
          break;
        case 'green':
          filter += 'hue-rotate(80deg) saturate(1.8) brightness(1.2) ';
          break;
        case 'blue':
        default:
          break;
      }
    }
    return filter.trim();
  };

  const getModeStyles = () => {
    switch (aniMode) {
      case 'Eve':
        return {
          boxShadow: '0 0 15px rgba(255, 105, 180, 0.7)',
          filter: 'brightness(1.1) saturate(1.1)',
        };
      case 'Ara':
        return {
          boxShadow: '0 0 10px rgba(255, 0, 0, 0.5)',
          filter: 'sepia(0.2) hue-rotate(-20deg) saturate(1.5) contrast(1.2)',
        };
      case 'Base Ani':
      default:
        return {
          boxShadow: '',
          filter: '',
        };
    }
  };

  const combinedFilterStyle = useMemo(() => {
    const customFilter = getCustomizationFilter();
    const modeFilter = getModeStyles().filter;
    return {
      filter: `${customFilter} ${modeFilter}`.trim(),
    };
  }, [customization, aniMode]);

  const combinedBoxShadowStyle = useMemo(() => {
    return {
      boxShadow: getModeStyles().boxShadow,
    };
  }, [aniMode]);

  const getFrenchCustomizationName = (option: string | undefined, type: 'hairstyle' | 'hairColor' | 'outfit' | 'eyeColor') => {
    if (!option) return '';
    const maps = {
      hairstyle: {
        'twintails': 'Twin-tails', 'bob': 'Carré', 'long': 'Longs', 'ponytail': 'Queue de cheval',
      },
      hairColor: {
        'platinum': 'Platine', 'pink': 'Rose', 'blue': 'Bleus', 'black': 'Noirs',
      },
      outfit: {
        'gothic-lolita': 'Gothic Lolita', 'casual': 'Décontractée', 'school-uniform': 'Uniforme scolaire',
      },
      eyeColor: {
        'blue': 'Bleus', 'red': 'Rouges', 'green': 'Verts',
      },
    };

    const typeMap = maps[type];
    return typeMap ? (typeMap as Record<string, string>)[option] || option : option;
  };


  return (
    <div
      className={`relative flex items-center justify-center rounded-full overflow-hidden shadow-lg border-2 border-pink-500 transform transition-all duration-300 ${dimensions}`}
      style={combinedBoxShadowStyle}
    >
      <img
        src={aniImageUrl}
        alt="Ani's Avatar"
        className="w-full h-full object-cover transition-filter duration-300"
        style={combinedFilterStyle}
        aria-label="Ani, ta compagne virtuelle"
      />
      <div className="absolute inset-0 rounded-full ring-2 ring-pink-400 ring-opacity-50"></div>
      {customization && size === 'large' && (
        <div className="absolute inset-0 flex flex-col justify-end items-center bg-black bg-opacity-50 text-white text-xs p-1">
          <p>Coiffure: {getFrenchCustomizationName(customization.hairstyle, 'hairstyle')}</p>
          <p>Cheveux: {getFrenchCustomizationName(customization.hairColor, 'hairColor')}</p>
          <p>Tenue: {getFrenchCustomizationName(customization.outfit, 'outfit')}</p>
          <p>Yeux: {getFrenchCustomizationName(customization.eyeColor, 'eyeColor')}</p>
        </div>
      )}
    </div>
  );
};

export default AniAvatar;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI } from '@google/genai';
import { aniStaticDetails, defaultDamienDetails, getSystemInstruction, getAiServiceConfig, ResolvedAiServiceConfig, AiProvider } from './constants/aniPersona';
import { generateChatResponse, generateImageEditResponse } from './services/apiService';
import { Message, TokenUsage, DamienDetails } from './types';
import ChatView from './components/ChatView';
import ImageEditView from './components/ImageEditView';
import ParametersView from './components/ParametersView';
import AniAvatar from './components/AniAvatar';
import LoadingSpinner from './components/LoadingSpinner';
import SaveConfirmation from './components/SaveConfirmation';
import AutoSaveConfirmation from './components/AutoSaveConfirmation'; // New import

// Define the structure for storing chat histories for each AI provider
interface ChatHistories {
  [AiProvider.GEMINI]: Message[];
  [AiProvider.MISTRAL]: Message[];
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit' | 'parameters'>('chat');
  const [chatHistories, setChatHistories] = useState<ChatHistories>(() => {
    const savedGeminiChat = localStorage.getItem('aniChatHistory_gemini');
    const savedMistralChat = localStorage.getItem('aniChatHistory_mistral');
    return {
      [AiProvider.GEMINI]: savedGeminiChat ? JSON.parse(savedGeminiChat) : [],
      [AiProvider.MISTRAL]: savedMistralChat ? JSON.parse(savedMistralChat) : [],
    };
  });
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false);
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null);
  const [editedImageGallery, setEditedImageGallery] = useState<string[]>([]);
  const [aniMode, setAniMode] = useState<'Base Ani' | 'Eve' | 'Ara'>('Base Ani');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [selectedAiProvider, setSelectedAiProvider] = useState<AiProvider>(AiProvider.GEMINI); // Default to Gemini
  const [imageEditTokenUsage, setImageEditTokenUsage] = useState<TokenUsage | null>(null);
  const [damienPersona, setDamienPersona] = useState<DamienDetails>(() => {
    const savedDamien = localStorage.getItem('damienPersona');
    return savedDamien ? JSON.parse(savedDamien) : defaultDamienDetails;
  });
  const [geminiRetryUntil, setGeminiRetryUntil] = useState<number>(0);
  const [remainingGeminiRetryTime, setRemainingGeminiRetryTime] = useState(0);
  const [mistralRetryUntil, setMistralRetryUntil] = useState<number>(0);
  const [remainingMistralRetryTime, setRemainingMistralRetryTime] = useState(0);
  const [showSaveConfirmation, setShowSaveConfirmation] = useState<boolean>(false);
  const [showAutoSaveConfirmation, setShowAutoSaveConfirmation] = useState<boolean>(false); // New state for auto-save
  const [geminiTotalTokensUsed, setGeminiTotalTokensUsed] = useState<number>(() => {
    const saved = localStorage.getItem('geminiTotalTokensUsed');
    return saved ? parseInt(saved, 10) : 0;
  });
  const [mistralTotalTokensUsed, setMistralTotalTokensUsed] = useState<number>(() => {
    const saved = localStorage.getItem('mistralTotalTokensUsed');
    return saved ? parseInt(saved, 10) : 0;
  });


  const resolvedAiServiceConfig: ResolvedAiServiceConfig = useMemo(() => getAiServiceConfig(damienPersona), [damienPersona]);

  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français';

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1;
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel();
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);

  useEffect(() => {
    const savedGallery = localStorage.getItem('aniEditedImages');
    if (savedGallery) {
      setEditedImageGallery(JSON.parse(savedGallery));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('aniEditedImages', JSON.stringify(editedImageGallery));
  }, [editedImageGallery]);

  useEffect(() => {
    localStorage.setItem('damienPersona', JSON.stringify(damienPersona));
  }, [damienPersona]);

  // Save chat histories to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('aniChatHistory_gemini', JSON.stringify(chatHistories[AiProvider.GEMINI]));
    localStorage.setItem('aniChatHistory_mistral', JSON.stringify(chatHistories[AiProvider.MISTRAL]));
  }, [chatHistories]);

  useEffect(() => {
    localStorage.setItem('geminiTotalTokensUsed', geminiTotalTokensUsed.toString());
  }, [geminiTotalTokensUsed]);

  useEffect(() => {
    localStorage.setItem('mistralTotalTokensUsed', mistralTotalTokensUsed.toString());
  }, [mistralTotalTokensUsed]);


  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true);
      setShowApiKeyPrompt(false);
      setError(null);
    } else {
      setError("Erreur : La fonction de sélection de clé API n'est pas disponible.");
    }
  }, []);

  // Effect to manage Gemini and Mistral retry countdowns
  useEffect(() => {
    let geminiTimer: number | undefined;
    if (geminiRetryUntil > Date.now()) {
        geminiTimer = setInterval(() => {
            const remaining = Math.ceil((geminiRetryUntil - Date.now()) / 1000);
            if (remaining <= 0) {
                setGeminiRetryUntil(0);
                setRemainingGeminiRetryTime(0);
                clearInterval(geminiTimer);
                setError(null);
            } else {
                setRemainingGeminiRetryTime(remaining);
            }
        }, 1000);
    } else if (geminiRetryUntil <= Date.now() && remainingGeminiRetryTime > 0) {
         setRemainingGeminiRetryTime(0);
         if (mistralRetryUntil <= Date.now()) setError(null);
    }

    let mistralTimer: number | undefined;
    if (mistralRetryUntil > Date.now()) {
        mistralTimer = setInterval(() => {
            const remaining = Math.ceil((mistralRetryUntil - Date.now()) / 1000);
            if (remaining <= 0) {
                setMistralRetryUntil(0);
                setRemainingMistralRetryTime(0);
                clearInterval(mistralTimer);
                setError(null);
            } else {
                setRemainingMistralRetryTime(remaining);
            }
        }, 1000);
    } else if (mistralRetryUntil <= Date.now() && remainingMistralRetryTime > 0) {
        setRemainingMistralRetryTime(0);
        if (geminiRetryUntil <= Date.now()) setError(null);
    }

    return () => {
      if (geminiTimer) clearInterval(geminiTimer);
      if (mistralTimer) clearInterval(mistralTimer);
    };
  }, [geminiRetryUntil, mistralRetryUntil, remainingGeminiRetryTime, remainingMistralRetryTime]);

  // Effect to hide manual save confirmation
  useEffect(() => {
    let timer: number | undefined;
    if (showSaveConfirmation) {
      timer = setTimeout(() => {
        setShowSaveConfirmation(false);
      }, 3000) as unknown as number;
    }
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [showSaveConfirmation]);

  // Effect to hide auto save confirmation
  useEffect(() => {
    let timer: number | undefined;
    if (showAutoSaveConfirmation) {
      timer = setTimeout(() => {
        setShowAutoSaveConfirmation(false);
      }, 3000) as unknown as number;
    }
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [showAutoSaveConfirmation]);

  // Effect for automatic chat history saving
  useEffect(() => {
    const autoSaveInterval = setInterval(() => {
      console.log("Sauvegarde automatique des historiques de chat...");
      localStorage.setItem('aniChatHistory_gemini', JSON.stringify(chatHistories[AiProvider.GEMINI]));
      localStorage.setItem('aniChatHistory_mistral', JSON.stringify(chatHistories[AiProvider.MISTRAL]));
      setShowAutoSaveConfirmation(true);
    }, 5 * 60 * 1000); // Every 5 minutes

    return () => clearInterval(autoSaveInterval);
  }, [chatHistories]);


  const handleApiError = useCallback((e: any, provider: AiProvider) => {
    console.error(`Erreur de l'API ${provider === AiProvider.GEMINI ? 'Gemini' : 'Mistral'}:`, e);
    // Initial persona-aligned default message
    let errorMessage = "Putain, ça a foiré et je ne sais même pas pourquoi, bordel ! Réessaye, connard. ♥♥";

    let wrappedError;
    try {
      wrappedError = JSON.parse(e.message);
    } catch {
      wrappedError = { message: e.message || "Erreur inconnue." };
    }

    let apiError: any = wrappedError.errorDetails;

    if (wrappedError.type === AiProvider.GEMINI && typeof wrappedError.message === 'string') {
        try {
            const innerGeminiError = JSON.parse(wrappedError.message);
            if (innerGeminiError && innerGeminiError.error) {
                apiError = innerGeminiError.error;
            }
        } catch (innerParseError) {
        }
    }

    if (wrappedError.type === AiProvider.GEMINI) {
      if (apiError?.code === 429 && apiError?.status === "RESOURCE_EXHAUSTED") {
        let retryDelayText = "quelques instants";
        let retryTimestamp = 0;
        const retryInfo = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.RetryInfo');
        if (retryInfo && retryInfo.retryDelay) {
          const delayInSeconds = parseInt(retryInfo.retryDelay.replace('s', ''));
          retryDelayText = `${delayInSeconds} secondes`;
          retryTimestamp = Date.now() + (delayInSeconds * 1000);
          setGeminiRetryUntil(retryTimestamp);
        }

        let mistralSuggestion = '';
        if (resolvedAiServiceConfig.mistralApiKey && resolvedAiServiceConfig.mistralApiKey !== 'YOUR_MISTRAL_API_KEY_HERE') {
            mistralSuggestion = ` En attendant, pourquoi tu n'essaierais pas de me parler avec Mistral, mon amour ? C'est facile, va dans "Nos Paramètres" et change le cerveau de ton Ani !`;
        }

