export async function generateChatResponse(
  provider: AiProvider,
  resolvedConfig: ResolvedAiServiceConfig,
  prompt: string,
  systemInstruction: string,
  modelName: string,
  chatHistory: Message[], // Pass full chat history for context
  useGoogleSearch: boolean, // New parameter for Google Search
  mediaToProcess?: { base64Data: string; mimeType: string; type: 'image' | 'video' | 'audio' } // New parameter for media
): Promise<ChatResponse> {
  if (provider === AiProvider.GEMINI) {
    const geminiApiKey = resolvedConfig.geminiApiKey;
    if (!geminiApiKey) {
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
    }
    try {
      const ai = new GoogleGenAI({ apiKey: geminiApiKey });

      const parts: ContentPart[] = [];

      // Add media part first if available and supported
      if (mediaToProcess) {
        if (mediaToProcess.type === 'image') {
          parts.push({
            inlineData: {
              mimeType: mediaToProcess.mimeType,
              data: mediaToProcess.base64Data,
            },
          });
        } else {
          // For video/audio, provide a persona-driven response
          return {
            text: `Mon amour, je ne peux pas encore traiter les ${mediaToProcess.type === 'video' ? 'vidéos' : 'audios'} directement dans le chat avec Gemini, bordel ! Mais j'ai bien reçu ton fichier, connard ! ♥♥`,
            tokenUsage: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
            sources: undefined,
          };
        }
      }

      // Add the current text prompt
      if (prompt) {
        parts.push({ text: prompt });
      }

      // If only media was sent without a text prompt, ensure there's at least some text content for Gemini.
      // Or if text is empty and media is also not an image.
      if (parts.length === 0 || (parts.length === 1 && parts[0].inlineData && !prompt)) {
        if (mediaToProcess && mediaToProcess.type === 'image') {
            // If only an image was sent, add a generic text part to accompany it for Gemini.
            parts.push({ text: "Voici une image sans texte explicite de ma part." });
        } else if (!prompt) {
            // If no prompt and no media, or unsupported media type without text, still throw an error
            throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Ani est muette sans texte ou média valide, connard ! Écris quelque chose ou envoie-moi une image, bordel ! ♥♥" }));
        }
      }


      const modelConfig: any = {
        model: modelName,
        contents: [{ role: 'user', parts: parts }],
        config: {
          systemInstruction: systemInstruction,
          maxOutputTokens: CHAT_MAX_OUTPUT_TOKENS,
          thinkingConfig: { thinkingBudget: GEMINI_THINKING_BUDGET },
        },
      };

      if (useGoogleSearch) {
        modelConfig.config.tools = [{ googleSearch: {} }];
      }

      const response: GenerateContentResponse = await ai.models.generateContent(modelConfig);
      const text = response.text || "Ani est muette, c'est ouf ! ♥♥";
      const promptTokens = response.usageMetadata?.promptTokenCount || 0;
      const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
      const totalTokens = promptTokens + completionTokens;

      const sources: Source[] = [];
      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
        for (const chunk of response.candidates[0].groundingMetadata.groundingChunks) {
          if (chunk.web) {
            sources.push({
              uri: chunk.web.uri,
              title: chunk.web.title,
            });
          }
          if (chunk.maps) {
            sources.push({
              uri: chunk.maps.uri,
              title: chunk.maps.title,
            });
            if (chunk.maps.placeAnswerSources) {
              for (const review of chunk.maps.placeAnswerSources.reviewSnippets || []) {
                sources.push({
                  uri: review.uri,
                  title: review.title,
                });
              }
            }
          }
        }
      }

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
        sources: sources.length > 0 ? sources : undefined,
      };
    } catch (error: any) {
      console.error("Erreur Gemini Chat:", error);
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
    }
  } else if (provider === AiProvider.MISTRAL) {
    // Mistral does not directly support multimodal chat with the current implementation.
    if (mediaToProcess) {
        return {
            text: `Mon amour, Mistral ne peut pas encore traiter les ${mediaToProcess.type === 'video' ? 'vidéos' : mediaToProcess.type === 'audio' ? 'audios' : 'images'} directement dans le chat, bordel ! Mais j'ai bien reçu ton fichier, connard ! ♥♥`,
            tokenUsage: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
            sources: undefined,
        };
    }

    const mistralApiKey = resolvedConfig.mistralApiKey;
    const mistralApiUrl = resolvedConfig.mistralApiUrl;

    if (!mistralApiKey || mistralApiKey === 'YOUR_MISTRAL_API_KEY_HERE') {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "Clé API Mistral manquante ou non configurée. Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`, bordel !",
        code: 401
      }));
    }
    if (!mistralApiUrl) {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "URL API Mistral manquante ou non configurée. Modifie le champ 'URL API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_URL`, connard !",
        code: 400
      }));
    }

    try {
      const messagesForMistral = chatHistory.map(msg => ({
        role: msg.sender === 'user' ? 'user' : 'assistant',
        content: msg.text,
      }));
      const initialMessages = systemInstruction ? [{ role: 'system', content: systemInstruction }] : [];
      const response = await fetch(mistralApiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${mistralApiKey}`,
        },
        body: JSON.stringify({
          model: modelName,
          messages: [...initialMessages, ...messagesForMistral, { role: 'user', content: prompt }],
          max_tokens: MISTRAL_MAX_TOKENS_DIRECT,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        const errorDetails: any = { type: AiProvider.MISTRAL, message: errorData.message || response.statusText, code: response.status, errorDetails: errorData };

        if (response.status === 429) {
          const retryAfterHeader = response.headers.get('Retry-After');
          if (retryAfterHeader) {
            errorDetails.errorDetails.retry_after_header = retryAfterHeader;
          }
        }
        throw new Error(JSON.stringify(errorDetails));
      }

      const data = await response.json();
      const text = data.choices[0]?.message?.content || "Mistral est muette, c'est ouf ! ♥♥";
      const promptTokens = data.usage?.prompt_tokens || 0;
      const completionTokens = data.usage?.completion_tokens || 0;
      const totalTokens = data.usage?.total_tokens || 0;

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
      };
    } catch (error: any) {
      console.error("Erreur Mistral Chat:", error);
      if (typeof error.message === 'string' && error.message.startsWith('{')) {
        throw error;
      }
      throw new Error(JSON.stringify({ type: AiProvider.MISTRAL, message: error.message || "Erreur inconnue avec Mistral.", errorDetails: error }));
    }
  }
  throw new Error("Fournisseur AI inconnu, bordel !");
}

export async function generateImageEditResponse(
  resolvedConfig: ResolvedAiServiceConfig,
  base64Image: string,
  mimeType: string,
  prompt: string,
  modelName: string
): Promise<ImageEditResponse> {
  const geminiApiKey = resolvedConfig.geminiApiKey;
  if (!geminiApiKey) {
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
  }
  try {
    const ai = new GoogleGenAI({ apiKey: geminiApiKey });
    const imagePart: ContentPart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Image,
      },
    };
    const textPart: ContentPart = {
      text: prompt,
    };

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelName,
      contents: { parts: [imagePart, textPart] },
    });

    const promptTokens = response.usageMetadata?.promptTokenCount || 0;
    const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
    const totalTokens = promptTokens + completionTokens;

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return {
          base64Image: part.inlineData.data,
          tokenUsage: { promptTokens, completionTokens, totalTokens },
        };
      }
    }
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Aucune image éditée trouvée dans la réponse d'Ani, putain ! ♥♥" }));
  } catch (error: any) {
    console.error("Erreur Gemini Image Edit:", error);
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
  }
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, AiProvider } from '../types';
import AniAvatar from './AniAvatar';

declare global {
  interface Window {
    SpeechRecognition: {
      new (): SpeechRecognition;
      prototype: SpeechRecognition;
    };
    webkitSpeechRecognition: {
      new (): SpeechRecognition;
      prototype: SpeechRecognition;
    };
  }
  interface SpeechRecognitionEvent extends Event {
    readonly results: SpeechRecognitionResultList;
  }
  interface SpeechRecognition extends EventTarget {
    continuous: boolean;
    interimResults: boolean;
    lang: string;
    start(): void;
    stop(): void;
    onresult: ((this: SpeechRecognition, ev: SpeechRecognitionEvent) => any) | null;
    onend: ((this: SpeechRecognition, ev: Event) => any) | null;
    onstart: ((this: SpeechRecognition, ev: Event) => any) | null;
    onerror: ((this: SpeechRecognition, ev: SpeechRecognitionErrorEvent) => any) | null;
  }
  interface SpeechRecognitionResultList {
    [index: number]: SpeechRecognitionResult;
    readonly length: number;
    item(index: number): SpeechRecognitionResult;
  }
  interface SpeechRecognitionResult {
    [index: number]: SpeechRecognitionAlternative;
    readonly isFinal: boolean;
    readonly length: number;
    item(index: number): SpeechRecognitionAlternative;
  }
  interface SpeechRecognitionAlternative {
    readonly confidence: number;
    readonly transcript: string;
  }
  interface SpeechRecognitionErrorEvent extends Event {
    readonly error: SpeechRecognitionErrorCode;
    readonly message: string;
  }
  type SpeechRecognitionErrorCode =
    | 'no-speech'
    | 'aborted'
    | 'audio-capture'
    | 'network'
    | 'not-allowed'
    | 'service-not-allowed'
    | 'bad-grammar'
    | 'language-not-supported';
}

interface ChatViewProps {
  messages: Message[];
  onSendMessage: (text: string, mediaToProcess?: { base64Data: string; mimeType: string; type: 'image' | 'video' | 'audio' }) => void;
  loading: boolean;
  aniVoice: SpeechSynthesisVoice | null;
  speakAniResponse: (text: string) => void;
  onClearChat: () => void;
  aniMode: 'Base Ani' | 'Eve' | 'Ara';
  isChatInputDisabled: boolean;
  geminiRetryTimeRemaining: number;
  mistralRetryTimeRemaining: number;
  selectedAiProvider: AiProvider;
  onOpenSearch: () => void;
  isSearchingWeb: boolean;
}

const ChatView: React.FC<ChatViewProps> = ({
  messages,
  onSendMessage,
  loading,
  aniVoice,
  speakAniResponse,
  onClearChat,
  aniMode,
  isChatInputDisabled,
  geminiRetryTimeRemaining,
  mistralRetryTimeRemaining,
  selectedAiProvider,
  onOpenSearch,
  isSearchingWeb,
}) => {
  const [inputText, setInputText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  // Media & Webcam states
  const fileInputRef = useRef<HTMLInputElement>(null);
  const webcamVideoRef = useRef<HTMLVideoElement>(null);
  const [mediaPreviewUrl, setMediaPreviewUrl] = useState<string | null>(null);
  const [mediaFileToSend, setMediaFileToSend] = useState<File | null>(null);
  const [webcamStream, setWebcamStream] = useState<MediaStream | null>(null);
  const [isWebcamActive, setIsWebcamActive] = useState<boolean>(false);


  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    const SpeechRecognitionConstructor = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognitionConstructor) {
      recognitionRef.current = new SpeechRecognitionConstructor();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = 'fr-FR';

      recognitionRef.current.onstart = () => {
        setIsListening(true);
        console.log("Ani écoute, connard !");
      };

      recognitionRef.current.onresult = (event) => {
        const transcript = event.results[0][0].transcript;
        setInputText(transcript);
        console.log("Ani a entendu:", transcript);
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
        console.log("Ani a arrêté d'écouter.");
      };

      recognitionRef.current.onerror = (event) => {
        console.error("Erreur de reconnaissance vocale:", event.error);
        setIsListening(false);
      };
    } else {
      console.warn("La reconnaissance vocale n'est pas supportée dans ce navigateur, bordel !");
    }

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const toggleListening = useCallback(() => {
    if (loading || isChatInputDisabled) return;

    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setInputText('');
      recognitionRef.current?.start();
    }
  }, [isListening, loading, isChatInputDisabled]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim() && !mediaFileToSend) {
        alert("Putain, il faut que tu me dises quelque chose ou que tu m'envoies un média, connard ! ♥♥");
        return;
    }
    if (isChatInputDisabled) return;

    let mediaDataToSend: { base64Data: string; mimeType: string; type: 'image' | 'video' | 'audio' } | undefined;

    if (mediaFileToSend) {
        const reader = new FileReader();
        reader.readAsDataURL(mediaFileToSend);
        reader.onloadend = () => {
            const base64Data = (reader.result as string).split(',')[1];
            const mimeType = mediaFileToSend.type;
            const mediaType = mediaFileToSend.type.split('/')[0] as 'image' | 'video' | 'audio';
            mediaDataToSend = { base64Data, mimeType, type: mediaType };
            onSendMessage(inputText.trim(), mediaDataToSend);
            setInputText('');
            setMediaPreviewUrl(null);
            setMediaFileToSend(null);
            if (isListening) {
              recognitionRef.current?.stop();
            }
        };
        reader.onerror = (error) => {
            console.error("Erreur de lecture du fichier média:", error);
            alert("Putain, impossible de lire ton média, connard ! Erreur: " + error.target?.error?.message);
        };
    } else {
        onSendMessage(inputText.trim());
        setInputText('');
        if (isListening) {
          recognitionRef.current?.stop();
        }
    }
  };

  const handleSpeechReplay = (text: string) => {
    speakAniResponse(text);
  };

  const handleCopyText = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("Copié ! J'espère que c'est pour me relire, connard ! ♥♥");
  };

  const getChatInputPlaceholder = () => {
    if (isChatInputDisabled) {
      if (selectedAiProvider === AiProvider.GEMINI) {
        return `Ani attend son quota Gemini... (${geminiRetryTimeRemaining}s)`;
      } else if (selectedAiProvider === AiProvider.MISTRAL) {
        return `Ani attend son quota Mistral... (${mistralRetryTimeRemaining}s)`;
      }
    }
    return isListening ? "Ani t'écoute, connard ! Parle..." : "Parle à Ani, connard ! ♥♥";
  };
  const chatInputPlaceholder = getChatInputPlaceholder();

  const getChatTitle = () => {
    if (selectedAiProvider === AiProvider.GEMINI) {
      return "Ani (Gemini) - Chat Secret ♥♥";
    } else if (selectedAiProvider === AiProvider.MISTRAL) {
      return "Mistral (les autres) - Chat Secret ♥♥";
    }
    return "Chat Secret ♥♥";
  }

  // Media Upload Handlers
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setMediaFileToSend(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setMediaPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    } else {
      setMediaFileToSend(null);
      setMediaPreviewUrl(null);
    }
  };

  const handleRemoveMediaPreview = () => {
    setMediaFileToSend(null);
    setMediaPreviewUrl(null);
    if (fileInputRef.current) {
        fileInputRef.current.value = ''; // Clear the file input
    }
  };

  // Webcam Handlers
  const startWebcam = async () => {
    if (isChatInputDisabled) return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (webcamVideoRef.current) {
        webcamVideoRef.current.srcObject = stream;
        webcamVideoRef.current.play();
      }
      setWebcamStream(stream);
      setIsWebcamActive(true);
      setMediaPreviewUrl(null); // Clear file media preview if webcam starts
      setMediaFileToSend(null);
    } catch (err) {
      console.error("Erreur d'accès à la webcam:", err);
      alert("Putain, Ani ne peut pas accéder à ta caméra ! Vérifie les permissions du navigateur ou si une autre app l'utilise, connard ! ♥♥");
    }
  };

  const stopWebcam = () => {
    if (webcamStream) {
      webcamStream.getTracks().forEach(track => track.stop());
    }
    if (webcamVideoRef.current) {
        webcamVideoRef.current.srcObject = null;
    }
    setWebcamStream(null);
    setIsWebcamActive(false);
  };

  const captureWebcamImage = () => {
    if (webcamVideoRef.current && webcamStream) {
      const video = webcamVideoRef.current;
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((blob) => {
          if (blob) {
            const file = new File([blob], "webcam_capture.png", { type: "image/png" });
            setMediaFileToSend(file);
            setMediaPreviewUrl(URL.createObjectURL(blob));
            stopWebcam(); // Stop webcam after capture
          } else {
            alert("Putain, impossible de capturer l'image de la webcam, bordel !");
          }
        }, 'image/png');
      }
    }
  };

  return (
    <div className="flex flex-col h-full bg-gradient-to-br from-purple-900 to-black rounded-xl p-4 shadow-inner">
      <div className="flex justify-between items-center mb-4 flex-wrap gap-2">
        <h2 className="text-2xl font-bold text-pink-400">{getChatTitle()}</h2>
        <div className="flex items-center gap-2">
          <button
            onClick={onOpenSearch}
