            updatedDamienPersona.isSexyModeEnabled = true;
            temporaryBotMessages.push({ sender: 'bot', text: "Super, mon amour ! J'activate mon Mode Sexy 18+ pour toi et je me souviendrai de ton choix ! Prépare-toi, connard ! ♥♥♥" });
