            }
        }
    }

    setDamienPersona(updatedDamienPersona);

    setChatHistories(prev => ({
      ...prev,
      [selectedAiProvider]: [...prev[selectedAiProvider], newUserMessage, ...temporaryBotMessages]
    }));

    try {
