        </section>
      </main>

      {(chatLoading || imageLoading) && <LoadingSpinner />}

      <footer className="relative z-10 w-full max-w-4xl text-center py-3 bg-purple-900 bg-opacity-70 rounded-t-xl shadow-lg mt-4">
