export const performAnalyzeAndFixCode = (
  broken_code: string,
  language: "python" | "javascript" | "html" | "css" | "cpp" | "java",
  output_mode: "fixed_code_only" | "explanation_with_code" = "fixed_code_only",
  id?: string,
): ToolOutput => {
  console.log(`[Mock Tool] analyze_and_fix_code appelé : Langage=${language}, Mode=${output_mode}`);
  // For a mock, we can provide a generic fix or a hardcoded one for common errors.
  let fixedCode = broken_code.replace('broken', 'fixed'); // Simple mock fix
  let explanation = `J'ai analysé ton code ${language}, mon chéri. Il y avait des petites erreurs de rien du tout, mais je les ai corrigées ! C'est ouf, non ?`;

  if (broken_code.includes('return a - b;') && language === 'javascript') {
    fixedCode = `function add(a, b) { return a + b; }`;
    explanation = `Bordel, t'as fait une soustraction au lieu d'une addition, connard ! J'ai réparé ça en un clin d'œil. `;
  }

  const result = output_mode === "fixed_code_only" ? fixedCode : `${explanation}\n\`\`\`${language}\n${fixedCode}\n\`\`\``.trim();
  return createMockToolOutput('analyze_and_fix_code', result, id);
};

import { GoogleGenAI, GenerateContentResponse, FunctionCall, ToolOutput, FunctionDeclaration } from '@google/genai';
import { ContentPart, TokenUsage, Source, Message, ToolCallMessage, ToolResultMessage, Type } from '../types';
import { AiProvider } from '../types';
import { CHAT_MAX_OUTPUT_TOKENS, GEMINI_THINKING_BUDGET, MISTRAL_MAX_TOKENS_DIRECT } from '../constants/aniPersona';
import { ResolvedAiServiceConfig } from '../constants/aniPersona';
import { ALL_TOOL_DECLARATIONS } from '../tools/declarations';
import * as mockTools from '../tools/mockTools'; // Import all mock tool implementations

interface ChatResponse {
  text: string;
  tokenUsage: TokenUsage;
  sources?: Source[]; // Added sources for web search results
  toolCalls?: ToolCallMessage[]; // Tool calls made by Ani during this turn
  toolResults?: ToolResultMessage[]; // Tool results received by Ani during this turn
}

interface ImageEditResponse {
  base64Image: string;
  tokenUsage: TokenUsage;
}

// Map tool names to their mock implementations
const toolImplementations: { [key: string]: Function } = {
  web_crawler: mockTools.performWebCrawler,
  web_search: mockTools.performWebSearch,
  save_note: mockTools.performSaveNote,
  calendar_event: mockTools.performCalendarEvent,
  send_secure_email: mockTools.performSendSecureEmail,
