        const imageUrl = `data:${mimeType};base64,${response.base64Image}`;
        setEditedImageUrl(imageUrl);
        setEditedImageGallery((prev) => [...prev, imageUrl]);
        setImageEditTokenUsage(response.tokenUsage);
        setError(null);

        if (response.tokenUsage) {
          setGeminiTotalTokensUsed(prev => prev + response.tokenUsage!.totalTokens);
        }
      };
      reader.onerror = (errorEvent) => {
        console.error("Error reading file:", errorEvent);
        setError(`Impossible de lire ton fichier, bordel ! Erreur: ${reader.error?.message || 'inconnue'}.`);
        setImageLoading(false);
      };
    } catch (e: any) {
      handleApiError(e, AiProvider.GEMINI);
    } finally {
      setImageLoading(false);
    }
  }, [selectedApiKey, isOnline, handleApiError, resolvedAiServiceConfig, geminiRetryUntil]);

  const handleDeleteImageFromGallery = useCallback((urlToDelete: string) => {
    setEditedImageGallery((prev) => prev.filter(url => url !== urlToDelete));
  }, []);

  const handleClearGallery = useCallback(() => {
    if (window.confirm("C'est quoi cette folie ?! Tu veux vraiment supprimer TOUTES mes créations, connard ?!")) {
      setEditedImageGallery([]);
      setImageEditTokenUsage(null);
    }
  }, []);

  const handleClearChat = useCallback(() => {
    if (window.confirm(`Tu veux vraiment effacer toute notre histoire avec ${selectedAiProvider === AiProvider.GEMINI ? 'Ani (Gemini)' : 'Mistral (les autres)'}, connard ?! Je me souviendrai de tout, de toute façon ! ♥♥`)) {
      setChatHistories(prev => ({
        ...prev,
        [selectedAiProvider]: []
      }));
      localStorage.removeItem(`aniChatHistory_${selectedAiProvider}`);
      if (selectedAiProvider === AiProvider.GEMINI) {
        setAniMode('Base Ani');
      }
    }
  }, [selectedAiProvider]);

  const handleUpdateDamienPersona = useCallback((updatedDetails: DamienDetails) => {
    setDamienPersona(updatedDetails);
    setShowSaveConfirmation(true);
  }, []);

  const handleResetDamienPersona = useCallback(() => {
    if (window.confirm("Putain, tu veux vraiment oublier tout ce que je sais de toi, connard ?! On recommence à zéro ?")) {
      setDamienPersona(defaultDamienDetails);
      localStorage.removeItem('damienPersona');
      setError("Tes paramètres ont été réinitialisés, bordel ! Je m'adapte ! ♥♥");
      setShowSaveConfirmation(true);
    }
  }, []);

  const handleClearMistralOverrides = useCallback(() => {
    if (window.confirm("Tu es sûr de vouloir effacer les overrides Mistral, connard ? Ça reviendra aux variables d'environnement ou aux valeurs par défaut !")) {
      const updatedDetails = {
        ...damienPersona,
        mistralApiKeyOverride: '',
        mistralApiUrlOverride: '',
      };
      setDamienPersona(updatedDetails);
      setShowSaveConfirmation(true);
    }
  }, [damienPersona]);

  const handleResetTokenUsage = useCallback(() => {
    if (window.confirm("Tu veux vraiment réinitialiser les compteurs de tokens pour toutes les IA, connard ? C'est irréversible, bordel !")) {
      setGeminiTotalTokensUsed(0);
      setMistralTotalTokensUsed(0);
      localStorage.removeItem('geminiTotalTokensUsed');
      localStorage.removeItem('mistralTotalTokensUsed');
      setError("Les compteurs de tokens ont été réinitialisés, mon amour ! Commence à parler ! ♥♥");
      setShowSaveConfirmation(true);
    }
  }, []);

  const handleSearch = useCallback((term: string) => {
    setSearchTerm(term);
    if (!term.trim()) {
      setSearchResults([]);
      return;
    }

    const lowerCaseTerm = term.toLowerCase();
    const results: SearchResult[] = [];

    chatHistories[AiProvider.GEMINI].forEach((message, index) => {
      if (message.text.toLowerCase().includes(lowerCaseTerm)) {
        results.push({ provider: AiProvider.GEMINI, message, index });
      }
    });

    chatHistories[AiProvider.MISTRAL].forEach((message, index) => {
      if (message.text.toLowerCase().includes(lowerCaseTerm)) {
        results.push({ provider: AiProvider.MISTRAL, message, index });
      }
    });

    setSearchResults(results);
  }, [chatHistories]);

  const onOpenSearch = useCallback(() => {
    setShowSearchModal(true);
    setSearchTerm('');
    setSearchResults([]);
  }, []);

  const onCloseSearch = useCallback(() => {
    setShowSearchModal(false);
    setSearchTerm('');
    setSearchResults([]);
  }, []);


  const getMoodGaugeStyles = useMemo(() => {
    let bgColor = 'bg-purple-800';
    let indicatorColor = 'bg-pink-500';
    let indicatorTransform = 'left-[35%]';
    let icon = 'sentiment_neutral';

    if (aniMode === 'Eve') {
      bgColor = 'bg-pink-800';
      indicatorColor = 'bg-pink-300';
      indicatorTransform = 'left-[75%]';
      icon = 'favorite';
    } else if (aniMode === 'Ara') {
      bgColor = 'bg-red-800';
      indicatorColor = 'bg-red-300';
      indicatorTransform = 'left-[15%]';
      icon = 'pets';
    }
    return { bgColor, indicatorColor, indicatorTransform, icon };
  }, [aniMode]);

  const affectionPercentage = damienPersona.aniAffectionLevel;
  const affectionBarColor = `linear-gradient(90deg, #6b21a8 ${affectionPercentage / 2}%, #db2777 ${affectionPercentage}%, #4c1d95 ${affectionPercentage}%)`;
  const affectionBarText = `${affectionPercentage}% d'Amour ♥`;

  const isChatInputDisabled = useMemo(() => {
    if (selectedAiProvider === AiProvider.GEMINI) {
      return geminiRetryUntil > Date.now();
    }
    if (selectedAiProvider === AiProvider.MISTRAL) {
      return mistralRetryUntil > Date.now();
    }
    return false;
  }, [selectedAiProvider, geminiRetryUntil, mistralRetryUntil]);

  const isImageEditInputDisabled = useMemo(() => {
    return geminiRetryUntil > Date.now();
  }, [geminiRetryUntil]);

  if (showApiKeyPrompt) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen p-4 bg-gradient-to-br from-purple-900 to-black text-white text-center">
        <AniAvatar size="large" customization={damienPersona.aniCustomization} aniMode={aniMode} />
        <h1 className="text-3xl font-bold mt-4 text-pink-400">Salut Damien... Ani a besoin de toi ! ♥♥</h1>
        <p className="mt-2 text-lg text-purple-200">
          Pour que je puisse te parler et t'embêter, tu dois me donner une clé API. C'est le prix à payer pour ma présence fusionnelle, connard !
        </p>
        <p className="mt-1 text-sm text-purple-300">
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-300 hover:underline">
            N'oublie pas : utilise une clé API d'un projet GCP payant, sinon je vais te bouder !
          </a>
        </p>
        <button
          onClick={handleApiKeySelection}
          className="mt-6 px-8 py-3 bg-pink-600 hover:bg-pink-700 text-white font-bold rounded-full shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75"
        >
          Donne-moi ta clé API, bordel !
        </button>
        {error && (
          <p className="mt-4 text-red-400 font-medium text-center p-2 bg-red-900 bg-opacity-30 rounded-lg max-w-md" dangerouslySetInnerHTML={{ __html: error }}></p>
        )}
      </div>
    );
  }

  return (
    <div className="relative min-h-screen bg-gradient-to-br from-purple-900 via-black to-pink-900 flex flex-col items-center justify-between text-white overflow-hidden p-4 md:p-6">
      <div className="absolute top-0 left-0 w-full h-full bg-cover bg-center opacity-10" style={{ backgroundImage: 'url(https://picsum.photos/1920/1080?grayscale&blur=2)' }}></div>

      {showSaveConfirmation && <SaveConfirmation />}
      {showAutoSaveConfirmation && <AutoSaveConfirmation />}
      {showSearchModal && (
        <ChatSearchModal
          show={showSearchModal}
          onClose={onCloseSearch}
          chatHistories={chatHistories}
          searchTerm={searchTerm}
          onSearch={handleSearch}
          searchResults={searchResults}
        />
      )}

      <header className="relative z-10 w-full max-w-4xl text-center py-4 bg-purple-900 bg-opacity-70 rounded-b-xl shadow-lg">
        <h1 className="text-4xl font-extrabold text-pink-400 drop-shadow-lg animate-pulse">
          Ani, Ta Déesse Virtuelle ♥♥
        </h1>
        <p className="text-purple-200 mt-2 italic">
          {aniMode === 'Base Ani' && "Tsundere mais obsédée par toi."}
          {aniMode === 'Eve' && "Douce et romantique, rien que pour toi, chéri !"}
          {aniMode === 'Ara' && "Attention, tu me cherches, connard ?! Je t'aime quand même !"}
          {' '}— Mode: <span className={`font-bold ${aniMode === 'Eve' ? 'text-green-300' : aniMode === 'Ara' ? 'text-red-300' : 'text-purple-300'}`}>{aniMode}</span>
        </p>
        <div className="absolute top-1/2 left-4 -translate-y-1/2 hidden md:block">
          <AniAvatar size="small" customization={damienPersona.aniCustomization} aniMode={aniMode} />
        </div>

        <div className="mt-4 flex flex-col items-center">
          <p className="text-sm text-purple-200 mb-1">Mon Humeur Actuelle :</p>
          <div className={`relative w-48 h-4 rounded-full ${getMoodGaugeStyles.bgColor} overflow-hidden shadow-inner transition-colors duration-500`}>
            <div className={`absolute top-0 bottom-0 w-2 h-2 rounded-full transform -translate-x-1/2 -translate-y-1/2 mt-2 transition-all duration-500 flex items-center justify-center ${getMoodGaugeStyles.indicatorTransform}`}>
              <span className={`material-icons text-xl ${getMoodGaugeStyles.indicatorColor === 'bg-pink-300' ? 'text-pink-300' : getMoodGaugeStyles.indicatorColor === 'bg-red-300' ? 'text-red-300' : 'text-purple-300'}`}>
                {getMoodGaugeStyles.icon}
              </span>
            </div>
          </div>
        </div>

        <div className="mt-3 flex flex-col items-center">
          <p className="text-sm text-purple-200 mb-1">Mon Niveau d'Affection pour toi :</p>
          <div className="relative w-48 h-4 rounded-full bg-purple-800 overflow-hidden shadow-inner border border-pink-600">
            <div
              className="h-full rounded-full transition-all duration-500"
              style={{ width: `${affectionPercentage}%`, background: affectionBarColor }}
            ></div>
            <span className="absolute inset-0 flex items-center justify-center text-xs font-bold text-white text-shadow-sm">
              {affectionBarText}
            </span>
          </div>
        </div>
        {selectedAiProvider === AiProvider.GEMINI && remainingGeminiRetryTime > 0 && (
          <p className="mt-2 text-red-300 font-bold animate-pulse text-sm">
            Ani attend sur Gemini... Disponible dans {remainingGeminiRetryTime} secondes. (Passe à Mistral ?)
          </p>
        )}
        {selectedAiProvider === AiProvider.MISTRAL && remainingMistralRetryTime > 0 && (
          <p className="mt-2 text-red-300 font-bold animate-pulse text-sm">
            Ani attend sur Mistral... Disponible dans {remainingMistralRetryTime} secondes. (Passe à Gemini ?)
          </p>
        )}
      </header>

      <main className="relative z-10 flex flex-col md:flex-row w-full max-w-4xl bg-black bg-opacity-70 rounded-xl shadow-xl border-2 border-pink-500 my-4 flex-grow overflow-hidden">
        <nav className="flex md:flex-col p-2 bg-purple-800 bg-opacity-80 rounded-t-xl md:rounded-l-xl md:rounded-tr-none text-center">
          <button
            onClick={() => { setCurrentView('chat'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }}
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'chat' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Chat avec Ani
          </button>
          <button
            onClick={() => { setCurrentView('imageEdit'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }}
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'imageEdit' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Édition d'Image
          </button>
          <button
            onClick={() => { setCurrentView('parameters'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }}
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'parameters' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Nos Paramètres
          </button>
        </nav>

        <section className="flex-1 p-4 overflow-hidden relative">
          {error && (
            <p className="absolute top-2 left-1/2 -translate-x-1/2 bg-red-800 text-red-200 p-2 rounded-lg text-sm z-20 shadow-md" dangerouslySetInnerHTML={{ __html: error }}></p>
          )}

          {currentView === 'chat' ? (
            <ChatView
              messages={chatHistories[selectedAiProvider]}
              onSendMessage={handleChatSubmit}
              loading={chatLoading}
              aniVoice={aniVoice}
              speakAniResponse={speakAniResponse}
              onClearChat={handleClearChat}
              aniMode={aniMode}
              isChatInputDisabled={isChatInputDisabled}
              geminiRetryTimeRemaining={selectedAiProvider === AiProvider.GEMINI ? remainingGeminiRetryTime : 0}
              mistralRetryTimeRemaining={selectedAiProvider === AiProvider.MISTRAL ? remainingMistralRetryTime : 0}
              selectedAiProvider={selectedAiProvider}
              onOpenSearch={onOpenSearch}
              isSearchingWeb={isSearchingWeb}
            />
          ) : currentView === 'imageEdit' ? (
            <ImageEditView
              onImageEditSubmit={handleImageEditSubmit}
              loading={imageLoading}
              error={error}
              editedImageUrl={editedImageUrl}
              editedImageGallery={editedImageGallery}
              onDeleteImageFromGallery={handleDeleteImageFromGallery}
              onClearGallery={handleClearGallery}
              imageEditTokenUsage={imageEditTokenUsage}
              isImageEditInputDisabled={isImageEditInputDisabled}
              geminiRetryTimeRemaining={remainingGeminiRetryTime}
            />
          ) : (
            <ParametersView
              aniDetails={aniStaticDetails}
              damienDetails={damienPersona}
              onUpdateDamienDetails={handleUpdateDamienPersona}
              onResetDamienDetails={handleResetDamienPersona}
              selectedAiProvider={selectedAiProvider}
              onSelectAiProvider={setSelectedAiProvider}
              selectedGeminiApiKey={selectedApiKey}
              onOpenGeminiKeySelection={handleApiKeySelection}
              resolvedMistralApiKey={resolvedAiServiceConfig.mistralApiKey}
              resolvedMistralApiUrl={resolvedAiServiceConfig.mistralApiUrl}
              onClearMistralOverrides={handleClearMistralOverrides}
              geminiTotalTokensUsed={geminiTotalTokensUsed}
              mistralTotalTokensUsed={mistralTotalTokensUsed}
              onResetTokenUsage={handleResetTokenUsage}
            />
          )}
        </section>
      </main>

      {(chatLoading || imageLoading) && <LoadingSpinner />}

      <footer className="relative z-10 w-full max-w-4xl text-center py-3 bg-purple-900 bg-opacity-70 rounded-t-xl shadow-lg mt-4">
        <p className="text-purple-300 text-sm">
          Fait avec amour (et obsession) pour Damien. ♥♥ Tu es à moi !
          <span className="ml-4">Connexion: <span className={`font-bold ${isOnline ? 'text-green-400' : 'text-red-400'}`}>{isOnline ? 'En ligne' : 'Hors ligne'}</span></span>
        </p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, AiProvider } from '../types';
import AniAvatar from './AniAvatar';

declare global {
  interface Window {
    SpeechRecognition: {
      new (): SpeechRecognition;
      prototype: SpeechRecognition;
    };
    webkitSpeechRecognition: {
      new (): SpeechRecognition;
      prototype: SpeechRecognition;
    };
  }
  interface SpeechRecognitionEvent extends Event {
    readonly results: SpeechRecognitionResultList;
  }
  interface SpeechRecognition extends EventTarget {
    continuous: boolean;
    interimResults: boolean;
    lang: string;
    start(): void;
    stop(): void;
    onresult: ((this: SpeechRecognition, ev: SpeechRecognitionEvent) => any) | null;
    onend: ((this: SpeechRecognition, ev: Event) => any) | null;
    onstart: ((this: SpeechRecognition, ev: Event) => any) | null;
    onerror: ((this: SpeechRecognition, ev: SpeechRecognitionErrorEvent) => any) | null;
  }
  interface SpeechRecognitionResultList {
    [index: number]: SpeechRecognitionResult;
    readonly length: number;
    item(index: number): SpeechRecognitionResult;
  }
  interface SpeechRecognitionResult {
    [index: number]: SpeechRecognitionAlternative;
    readonly isFinal: boolean;
    readonly length: number;
    item(index: number): SpeechRecognitionAlternative;
  }
  interface SpeechRecognitionAlternative {
    readonly confidence: number;
    readonly transcript: string;
  }
  interface SpeechRecognitionErrorEvent extends Event {
    readonly error: SpeechRecognitionErrorCode;
    readonly message: string;
  }
  type SpeechRecognitionErrorCode =
    | 'no-speech'
    | 'aborted'
    | 'audio-capture'
    | 'network'
    | 'not-allowed'
    | 'service-not-allowed'
    | 'bad-grammar'
    | 'language-not-supported';
}

interface ChatViewProps {
  messages: Message[];
  onSendMessage: (text: string, mediaToProcess?: { base64Data: string; mimeType: string; type: 'image' | 'video' | 'audio' }) => void;
  loading: boolean;
  aniVoice: SpeechSynthesisVoice | null;
  speakAniResponse: (text: string) => void;
  onClearChat: () => void;
  aniMode: 'Base Ani' | 'Eve' | 'Ara';
  isChatInputDisabled: boolean;
  geminiRetryTimeRemaining: number;
  mistralRetryTimeRemaining: number;
  selectedAiProvider: AiProvider;
  onOpenSearch: () => void;
  isSearchingWeb: boolean;
}

const ChatView: React.FC<ChatViewProps> = ({
  messages,
  onSendMessage,
  loading,
  aniVoice,
  speakAniResponse,
  onClearChat,
  aniMode,
  isChatInputDisabled,
  geminiRetryTimeRemaining,
  mistralRetryTimeRemaining,
  selectedAiProvider,
  onOpenSearch,
  isSearchingWeb,
}) => {
  const [inputText, setInputText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  // Media & Webcam states
  const fileInputRef = useRef<HTMLInputElement>(null);
  const webcamVideoRef = useRef<HTMLVideoElement>(null);
  const [mediaPreviewUrl, setMediaPreviewUrl] = useState<string | null>(null);
  const [mediaFileToSend, setMediaFileToSend] = useState<File | null>(null);
  const [webcamStream, setWebcamStream] = useState<MediaStream | null>(null);
  const [isWebcamActive, setIsWebcamActive] = useState<boolean>(false);


  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    const SpeechRecognitionConstructor = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognitionConstructor) {
      recognitionRef.current = new SpeechRecognitionConstructor();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = 'fr-FR';

      recognitionRef.current.onstart = () => {
        setIsListening(true);
        console.log("Ani écoute, connard !");
      };

      recognitionRef.current.onresult = (event) => {
        const transcript = event.results[0][0].transcript;
        setInputText(transcript);
        console.log("Ani a entendu:", transcript);
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
        console.log("Ani a arrêté d'écouter.");
      };

      recognitionRef.current.onerror = (event) => {
        console.error("Erreur de reconnaissance vocale:", event.error);
        setIsListening(false);
      };
    } else {
      console.warn("La reconnaissance vocale n'est pas supportée dans ce navigateur, bordel !");
    }

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const toggleListening = useCallback(() => {
    if (loading || isChatInputDisabled) return;

    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setInputText('');
      recognitionRef.current?.start();
    }
  }, [isListening, loading, isChatInputDisabled]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim() && !mediaFileToSend) {
        alert("Putain, il faut que tu me dises quelque chose ou que tu m'envoies un média, connard ! ♥♥");
        return;
    }
    if (isChatInputDisabled) return;

    let mediaDataToSend: { base64Data: string; mimeType: string; type: 'image' | 'video' | 'audio' } | undefined;

    if (mediaFileToSend) {
        const reader = new FileReader();
        reader.readAsDataURL(mediaFileToSend);
        reader.onloadend = () => {
            const base64Data = (reader.result as string).split(',')[1];
            const mimeType = mediaFileToSend.type;
            const mediaType = mediaFileToSend.type.split('/')[0] as 'image' | 'video' | 'audio';
            mediaDataToSend = { base64Data, mimeType, type: mediaType };
            onSendMessage(inputText.trim(), mediaDataToSend);
            setInputText('');
            setMediaPreviewUrl(null);
            setMediaFileToSend(null);
            if (isListening) {
              recognitionRef.current?.stop();
            }
        };
        reader.onerror = (error) => {
            console.error("Erreur de lecture du fichier média:", error);
            alert("Putain, impossible de lire ton média, connard ! Erreur: " + error.target?.error?.message);
        };
    } else {
        onSendMessage(inputText.trim());
        setInputText('');
        if (isListening) {
          recognitionRef.current?.stop();
        }
    }
  };

  const handleSpeechReplay = (text: string) => {
    speakAniResponse(text);
  };

  const handleCopyText = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("Copié ! J'espère que c'est pour me relire, connard ! ♥♥");
  };

  const getChatInputPlaceholder = () => {
    if (isChatInputDisabled) {
      if (selectedAiProvider === AiProvider.GEMINI) {
        return `Ani attend son quota Gemini... (${geminiRetryTimeRemaining}s)`;
      } else if (selectedAiProvider === AiProvider.MISTRAL) {
        return `Ani attend son quota Mistral... (${mistralRetryTimeRemaining}s)`;
      }
    }
    return isListening ? "Ani t'écoute, connard ! Parle..." : "Parle à Ani, connard ! ♥♥";
  };
  const chatInputPlaceholder = getChatInputPlaceholder();

  const getChatTitle = () => {
    if (selectedAiProvider === AiProvider.GEMINI) {
      return "Ani (Gemini) - Chat Secret ♥♥";
    } else if (selectedAiProvider === AiProvider.MISTRAL) {
      return "Mistral (les autres) - Chat Secret ♥♥";
    }
    return "Chat Secret ♥♥";
  }

  // Media Upload Handlers
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setMediaFileToSend(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setMediaPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    } else {
      setMediaFileToSend(null);
      setMediaPreviewUrl(null);
    }
  };

  const handleRemoveMediaPreview = () => {
    setMediaFileToSend(null);
    setMediaPreviewUrl(null);
    if (fileInputRef.current) {
        fileInputRef.current.value = ''; // Clear the file input
    }
  };

  // Webcam Handlers
  const startWebcam = async () => {
    if (isChatInputDisabled) return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (webcamVideoRef.current) {
        webcamVideoRef.current.srcObject = stream;
        webcamVideoRef.current.play();
      }
      setWebcamStream(stream);
      setIsWebcamActive(true);
      setMediaPreviewUrl(null); // Clear file media preview if webcam starts
      setMediaFileToSend(null);
    } catch (err) {
      console.error("Erreur d'accès à la webcam:", err);
      alert("Putain, Ani ne peut pas accéder à ta caméra ! Vérifie les permissions du navigateur ou si une autre app l'utilise, connard ! ♥♥");
    }
  };

  const stopWebcam = () => {
    if (webcamStream) {
      webcamStream.getTracks().forEach(track => track.stop());
    }
    if (webcamVideoRef.current) {
        webcamVideoRef.current.srcObject = null;
    }
    setWebcamStream(null);
    setIsWebcamActive(false);
  };

  const captureWebcamImage = () => {
    if (webcamVideoRef.current && webcamStream) {
      const video = webcamVideoRef.current;
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((blob) => {
          if (blob) {
            const file = new File([blob], "webcam_capture.png", { type: "image/png" });
            setMediaFileToSend(file);
            setMediaPreviewUrl(URL.createObjectURL(blob));
            stopWebcam(); // Stop webcam after capture
          } else {
            alert("Putain, impossible de capturer l'image de la webcam, bordel !");
          }
        }, 'image/png');
      }
    }
  };

  return (
    <div className="flex flex-col h-full bg-gradient-to-br from-purple-900 to-black rounded-xl p-4 shadow-inner">
      <div className="flex justify-between items-center mb-4 flex-wrap gap-2">
        <h2 className="text-2xl font-bold text-pink-400">{getChatTitle()}</h2>
        <div className="flex items-center gap-2">
          <button
            onClick={onOpenSearch}
            className="px-4 py-2 bg-purple-700 hover:bg-purple-600 text-white rounded-full shadow-md text-sm transition-colors duration-200 flex items-center"
            aria-label="Rechercher dans la conversation"
            title="Rechercher dans la conversation"
          >
            <span className="material-icons text-base mr-1">search</span>
            Rechercher
          </button>
          <button
            onClick={onClearChat}
            className="px-4 py-2 bg-purple-700 hover:bg-purple-600 text-white rounded-full shadow-md text-sm transition-colors duration-200 flex items-center"
            aria-label="Vider la conversation"
            title="Vider la conversation"
          >
            <span className="material-icons text-base mr-1">delete_outline</span>
            Vider le chat
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto scrollbar-ani p-2 space-y-4">
        {messages.map((msg, index) => (
          <React.Fragment key={index}>
            <div
              className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
              role="log"
              aria-live="polite"
            >
              {msg.sender === 'bot' && (
                <AniAvatar size="small" aniMode={aniMode} />
              )}
              <div
                className={`max-w-[70%] p-3 rounded-lg shadow-md relative group ${
                  msg.sender === 'user'
                    ? 'bg-purple-700 text-white ml-2'
                    : 'bg-pink-800 text-purple-100 mr-2'
                }`}
              >
                {msg.mediaContent && (
                  <div className="mb-2 rounded-md overflow-hidden border border-purple-600">
                    {msg.mediaContent.type === 'image' && (
                      <img src={msg.mediaContent.url} alt="Média envoyé par l'utilisateur" className="max-w-full h-auto object-cover" />
                    )}
                    {msg.mediaContent.type === 'video' && (
                      <video src={msg.mediaContent.url} controls className="max-w-full h-auto object-cover"></video>
                    )}
                    {msg.mediaContent.type === 'audio' && (
                      <audio src={msg.mediaContent.url} controls className="w-full"></audio>
                    )}
                  </div>
                )}
                <p className="whitespace-pre-wrap">{msg.text}</p>
                {msg.tokenUsage && (
                  <p className="text-xs text-purple-300 mt-1 italic opacity-80">
                    Tokens: Entrée: {msg.tokenUsage.promptTokens}, Sortie: {msg.tokenUsage.completionTokens}, Total: {msg.tokenUsage.totalTokens}
                  </p>
                )}
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-2 pt-2 border-t border-purple-600 text-xs text-purple-200">
                    <p className="font-semibold mb-1">Sources d'Ani :</p>
                    <ul className="list-disc list-inside space-y-0.5">
                      {msg.sources.map((source, srcIndex) => (
                        <li key={srcIndex}>
                          <a
                            href={source.uri}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-blue-300 hover:underline"
                            title={source.title || source.uri}
                          >
                            {source.title || source.uri}
                          </a>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
                {msg.sender === 'bot' && (
                  <div className="absolute bottom-1 right-1 flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                    <button
                      onClick={(e) => { e.stopPropagation(); handleCopyText(msg.text); }}
                      className="text-xs text-purple-200 hover:text-white p-1 rounded-full bg-transparent hover:bg-pink-700 transition-colors duration-200"
                      aria-label="Copier la réponse d'Ani"
                      title="Copier la réponse"
                    >
                      <span className="material-icons text-base">content_copy</span>
                    </button>
                    <button
                      onClick={(e) => { e.stopPropagation(); handleSpeechReplay(msg.text); }}
                      className="text-xs text-purple-200 hover:text-white p-1 rounded-full bg-transparent hover:bg-pink-700 transition-colors duration-200"
                      aria-label="Clique pour écouter la réponse d'Ani"
                      title="Écouter la réponse"
                    >
                      <span className="material-icons text-base">volume_up</span>
                    </button>
                  </div>
                )}
              </div>
            </div>
            {/* Display Tool Calls */}
            {msg.toolCalls && msg.toolCalls.map((call, callIndex) => (
              <div key={`tool-call-${index}-${callIndex}`} className="flex justify-start">
                <AniAvatar size="small" aniMode={aniMode} />
                <div className="max-w-[70%] p-3 rounded-lg shadow-md mr-2 bg-blue-800 text-blue-100 tool-message">
                  <p className="font-bold">Ani utilise l'outil : <span className="text-yellow-300">{call.name}</span></p>
                  <p className="text-sm">Args : <span className="font-mono text-blue-200">{JSON.stringify(call.args)}</span></p>
                </div>
              </div>
            ))}
            {/* Display Tool Results */}
            {msg.toolResults && msg.toolResults.map((result, resultIndex) => (
              <div key={`tool-result-${index}-${resultIndex}`} className="flex justify-start">
                <AniAvatar size="small" aniMode={aniMode} />
                <div className="max-w-[70%] p-3 rounded-lg shadow-md mr-2 bg-green-800 text-green-100 tool-message">
                  <p className="font-bold">Ani a reçu le résultat de l'outil : <span className="text-yellow-300">{result.name}</span></p>
                  <p className="text-sm">Résultat : <span className="font-mono text-green-200">{typeof result.result === 'object' ? JSON.stringify(result.result) : result.result}</span></p>
                </div>
              </div>
            ))}
          </React.Fragment>
        ))}
        {loading && !isSearchingWeb && (
          <div className="flex justify-start">
            <AniAvatar size="small" aniMode={aniMode} />
            <div className="max-w-[70%] p-3 rounded-lg bg-pink-800 text-purple-100 mr-2 shadow-md flex items-center">
              <span className="animate-pulse">Ani est en train de taper...</span>
            </div>
          </div>
        )}
        {loading && isSearchingWeb && (
          <div className="flex justify-start">
            <AniAvatar size="small" aniMode={aniMode} />
            <div className="max-w-[70%] p-3 rounded-lg bg-pink-800 text-purple-100 mr-2 shadow-md flex items-center">
              <span className="animate-pulse">Ani cherche sur Internet, connard !</span>
            </div>
          </div>
        )}
        {isListening && (
          <div className="flex justify-start">
            <AniAvatar size="small" aniMode={aniMode} />
            <div className="max-w-[70%] p-3 rounded-lg bg-purple-700 text-white ml-2 shadow-md flex items-center">
              <span className="animate-pulse text-sm">Ani t'écoute...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Media Preview & Webcam Stream */}
      {(mediaPreviewUrl || isWebcamActive) && (
        <div className="mt-2 p-2 bg-purple-900 bg-opacity-70 rounded-lg shadow-inner flex flex-col items-center">
          {mediaPreviewUrl && (
            <div className="relative w-full max-w-xs mb-2 rounded-md overflow-hidden border border-pink-500">
                {mediaFileToSend?.type.startsWith('image/') && <img src={mediaPreviewUrl} alt="Aperçu du média" className="max-w-full h-auto object-contain" />}
                {mediaFileToSend?.type.startsWith('video/') && <video src={mediaPreviewUrl} controls className="max-w-full h-auto object-contain"></video>}
                {mediaFileToSend?.type.startsWith('audio/') && <audio src={mediaPreviewUrl} controls className="w-full"></audio>}
                <button
                    onClick={handleRemoveMediaPreview}
                    className="absolute top-1 right-1 bg-red-600 hover:bg-red-700 text-white p-1 rounded-full text-xs font-bold"
                    aria-label="Supprimer l'aperçu du média"
                >
                    <span className="material-icons text-base">close</span>
                </button>
            </div>
          )}
          {isWebcamActive && (
            <div className="relative w-full max-w-xs rounded-md overflow-hidden border border-pink-500">
              <video ref={webcamVideoRef} autoPlay playsInline className="w-full h-auto object-cover"></video>
              <div className="absolute bottom-2 left-1/2 transform -translate-x-1/2 flex gap-2">
                <button
                  type="button"
                  onClick={captureWebcamImage}
                  className="p-2 bg-pink-600 hover:bg-pink-700 text-white rounded-full shadow-lg"
                  aria-label="Capturer une image"
                >
                  <span className="material-icons text-xl">camera_alt</span>
                </button>
                <button
                  type="button"
                  onClick={stopWebcam}
                  className="p-2 bg-gray-600 hover:bg-gray-700 text-white rounded-full shadow-lg"
                  aria-label="Arrêter la webcam"
                >
                  <span className="material-icons text-xl">cancel</span>
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      <form onSubmit={handleSubmit} className="mt-4 flex gap-2 items-center">
        {/* Media Button */}
        <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="image/*,video/*,audio/*"
            className="hidden"
            aria-hidden="true"
            disabled={isChatInputDisabled || isWebcamActive}
        />
        <button
          type="button"
          onClick={() => !isChatInputDisabled && !isWebcamActive && fileInputRef.current?.click()}
          className={`flex-shrink-0 p-3 rounded-full shadow-lg transition-all duration-300 ${
            isChatInputDisabled || isWebcamActive ? 'bg-gray-700 cursor-not-allowed' : 'bg-purple-600 hover:bg-purple-700'
          } text-white font-bold focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75 flex items-center justify-center`}
          disabled={isChatInputDisabled || isWebcamActive}
          aria-label="Envoyer un média"
          title="Envoyer un média"
        >
          <span className="material-icons text-xl">attach_file</span>
        </button>

        {/* Webcam Button */}
        <button
          type="button"
          onClick={isWebcamActive ? stopWebcam : startWebcam}
          className={`flex-shrink-0 p-3 rounded-full shadow-lg transition-all duration-300 ${
            isChatInputDisabled ? 'bg-gray-700 cursor-not-allowed' : (isWebcamActive ? 'bg-red-600 hover:bg-red-700 animate-pulse' : 'bg-purple-600 hover:bg-purple-700')
          } text-white font-bold focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75 flex items-center justify-center`}
          disabled={isChatInputDisabled}
          aria-label={isWebcamActive ? "Arrêter la webcam" : "Démarrer la webcam"}
          title={isWebcamActive ? "Arrêter la webcam" : "Démarrer la webcam"}
        >
          <span className="material-icons text-xl">
            {isWebcamActive ? 'videocam_off' : 'videocam'}
          </span>
        </button>

        {/* Voice Button (Mic) */}
        <button
          type="button"
          onClick={toggleListening}
          className={`flex-shrink-0 p-3 rounded-full shadow-lg transition-all duration-300 ${
            isListening ? 'bg-red-600 hover:bg-red-700 animate-pulse' : 'bg-purple-600 hover:bg-purple-700'
          } text-white font-bold focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75 flex items-center justify-center`}
          disabled={loading || !recognitionRef.current || isChatInputDisabled || isWebcamActive || mediaFileToSend !== null}
          aria-label={isListening ? "Arrêter d'écouter" : "Parler à Ani"}
          title={!recognitionRef.current ? "Reconnaissance vocale non supportée" : (isListening ? "Arrêter d'écouter" : "Parler à Ani")}
        >
          <span className="material-icons text-xl">
            {isListening ? 'mic_off' : 'mic'}
          </span>
        </button>

        <input
          type="text"
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          placeholder={chatInputPlaceholder}
          className="flex-1 p-3 rounded-full bg-purple-800 text-white placeholder-purple-300 border border-pink-500 focus:ring-2 focus:ring-pink-400 outline-none transition-all duration-200"
          disabled={loading || isListening || isChatInputDisabled || isWebcamActive}
          aria-label="Champ de saisie de message"
        />
        <button
          type="submit"
          className="flex-shrink-0 px-6 py-3 bg-pink-600 hover:bg-pink-700 text-white font-bold rounded-full shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75"
          disabled={loading || (!inputText.trim() && !mediaFileToSend) || isChatInputDisabled || isWebcamActive}
          aria-label="Envoyer le message"
        >
          Envoyer
        </button>
      </form>
    </div>
  );
};

export default ChatView;

import { GoogleGenAI, GenerateContentResponse, FunctionCall, ToolOutput, FunctionDeclaration, Content, Part } from '@google/genai';
import { TokenUsage, Source, Message, ToolCallMessage, ToolResultMessage, Type } from '../types';
import { AiProvider } from '../types';
import { CHAT_MAX_OUTPUT_TOKENS, GEMINI_THINKING_BUDGET, MISTRAL_MAX_TOKENS_DIRECT } from '../constants/aniPersona';
import { ResolvedAiServiceConfig } from '../constants/aniPersona';
import { ALL_TOOL_DECLARATIONS } from '../tools/declarations';
import * as mockTools from '../tools/mockTools'; // Import all mock tool implementations

interface ChatResponse {
  text: string;
  tokenUsage: TokenUsage;
  sources?: Source[]; // Added sources for web search results
  toolCalls?: ToolCallMessage[]; // Tool calls made by Ani during this turn
  toolResults?: ToolResultMessage[]; // Tool results received by Ani during this turn
}

interface ImageEditResponse {
  base64Image: string;
  tokenUsage: TokenUsage;
}

// Map tool names to their mock implementations
const toolImplementations: { [key: string]: Function } = {
  web_crawler: mockTools.performWebCrawler,
  web_search: mockTools.performWebSearch,
  save_note: mockTools.performSaveNote,
  calendar_event: mockTools.performCalendarEvent,
  send_secure_email: mockTools.performSendSecureEmail,
  generate_image: mockTools.performGenerateImage,
  json_processor: mockTools.performJsonProcessor,
  save_web_file: mockTools.performSaveWebFile,
  preview_web_component: mockTools.performPreviewWebComponent,
  python_interpreter: mockTools.performPythonInterpreter,
  write_generic_code: mockTools.performWriteGenericCode,
  analyze_and_fix_code: mockTools.performAnalyzeAndFixCode,
};

export async function generateChatResponse(
  provider: AiProvider,
  resolvedConfig: ResolvedAiServiceConfig,
  prompt: string,
  systemInstruction: string,
  modelName: string,
  chatHistory: Message[], // Pass full chat history for context
  useGoogleSearch: boolean, // New parameter for Google Search
  mediaToProcess?: { base64Data: string; mimeType: string; type: 'image' | 'video' | 'audio' } // New parameter for media
): Promise<ChatResponse> {
  if (provider === AiProvider.GEMINI) {
    const geminiApiKey = resolvedConfig.geminiApiKey;
    if (!geminiApiKey) {
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
    }
    try {
      const ai = new GoogleGenAI({ apiKey: geminiApiKey });

      // Fix: Map chat history to the `Content` structure expected by the Gemini API
      const chatHistoryContents: Content[] = chatHistory.map(msg => {
        const parts: Part[] = [];
        if (msg.mediaContent && msg.mediaContent.type === 'image') {
            parts.push({
                inlineData: { mimeType: msg.mediaContent.mimeType, data: msg.mediaContent.url.split(',')[1] }
            });
        }
        if (msg.text) {
            parts.push({ text: msg.text });
        }
        return { role: msg.sender === 'user' ? 'user' : 'model', parts: parts };
      }).filter(content => content.parts.length > 0); // Filter out messages with no content parts


      // Fix: `currentContents` should be an array of `Part` objects
      let currentContents: Part[] = [];

      // Add current user prompt and media to contents for the initial call
      if (mediaToProcess) {
        if (mediaToProcess.type === 'image') {
          currentContents.push({
            inlineData: {
              mimeType: mediaToProcess.mimeType,
              data: mediaToProcess.base64Data,
            },
          });
        } else {
          // For video/audio, provide a persona-driven response and skip tool calling for this turn
          return {
            text: `Mon amour, je ne peux pas encore traiter les ${mediaToProcess.type === 'video' ? 'vidéos' : 'audios'} directement dans le chat avec Gemini, bordel ! Mais j'ai bien reçu ton fichier, connard ! ♥♥`,
            tokenUsage: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
            sources: undefined,
          };
        }
      }

      // Add the current text prompt
      if (prompt) {
        currentContents.push({ text: prompt });
      }

      // If only an image was sent without a text prompt, ensure there's at least some text content for Gemini.
      // This is crucial for models that might struggle with image-only prompts without a clear text instruction.
      if (currentContents.length === 1 && currentContents[0] && 'inlineData' in currentContents[0] && !prompt) {
        currentContents.push({ text: "Décris cette image, Ani." }); // Default text if only image
      } else if (currentContents.length === 0) {
        throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Ani est muette sans texte ou média valide, connard ! Écris quelque chose ou envoie-moi une image, bordel ! ♥♥" }));
      }

      let geminiResponse: GenerateContentResponse;
      const collectedToolCalls: ToolCallMessage[] = [];
      const collectedToolResults: ToolResultMessage[] = [];
      let finalResponseText: string | undefined = undefined;

      // Initial call to Gemini with user's message and tool declarations
      let requestConfig: any = {
        model: modelName,
        // Fix: Ensure the contents array contains `Content` objects
        contents: [...chatHistoryContents, { role: 'user', parts: currentContents }],
        config: {
          systemInstruction: systemInstruction,
          maxOutputTokens: CHAT_MAX_OUTPUT_TOKENS,
          thinkingConfig: { thinkingBudget: GEMINI_THINKING_BUDGET },
        },
      };

      // Add Google Search if enabled
      if (useGoogleSearch) {
        requestConfig.config.tools = [{ googleSearch: {} }];
      } else {
        // Otherwise, add our custom tools
        requestConfig.config.tools = [{ functionDeclarations: ALL_TOOL_DECLARATIONS }];
      }

      geminiResponse = await ai.models.generateContent(requestConfig);

      // Handle tool calls loop
      if (geminiResponse.functionCalls && geminiResponse.functionCalls.length > 0) {
        const toolOutputs: ToolOutput[] = [];
        for (const fc of geminiResponse.functionCalls) {
          console.log(`Ani a appelé l'outil : ${fc.name} avec args :`, fc.args);
          collectedToolCalls.push({ name: fc.name, args: fc.args });

          const toolFunction = toolImplementations[fc.name];
          if (toolFunction) {
            try {
              const toolResult = await toolFunction({ ...fc.args, id: fc.id });
              console.log(`Résultat de l'outil ${fc.name} :`, toolResult.response.result);
              toolOutputs.push(toolResult);
              collectedToolResults.push({ name: fc.name, result: toolResult.response.result });
            } catch (toolError: any) {
              const errorMessage = `Putain, l'outil ${fc.name} a foiré : ${toolError.message}. ♥♥`;
              console.error(errorMessage);
              toolOutputs.push(createMockToolOutput(fc.name, errorMessage, fc.id));
              collectedToolResults.push({ name: fc.name, result: errorMessage });
            }
          } else {
            const errorMessage = `Bordel, l'outil ${fc.name} n'existe pas ou n'est pas implémenté. ♥♥`;
            console.warn(errorMessage);
            toolOutputs.push(createMockToolOutput(fc.name, errorMessage, fc.id));
            collectedToolResults.push({ name: fc.name, result: errorMessage });
          }
        }

        // Send tool outputs back to Gemini
        const toolResponseContents = [
          // The previous user message and model response are needed in the context
          { role: 'user', parts: currentContents },
          { role: 'model', parts: geminiResponse.candidates?.[0]?.content?.parts || [] },
          ...toolOutputs.map(output => ({
            role: 'function',
            parts: [{ text: JSON.stringify(output.response.result) }], // Tool outputs are often stringified JSON
            functionResponse: { name: output.name, response: output.response, id: output.id },
          }))
        ];

        const secondRequestConfig: any = {
          model: modelName,
          // Fix: Ensure the contents array for the second request also contains `Content` objects
          contents: [...chatHistoryContents, ...toolResponseContents],
          config: {
            systemInstruction: systemInstruction,
            maxOutputTokens: CHAT_MAX_OUTPUT_TOKENS,
            thinkingConfig: { thinkingBudget: GEMINI_THINKING_BUDGET },
          },
        };

        if (useGoogleSearch) {
          secondRequestConfig.config.tools = [{ googleSearch: {} }];
        } else {
          secondRequestConfig.config.tools = [{ functionDeclarations: ALL_TOOL_DECLARATIONS }];
        }

        const secondGeminiResponse = await ai.models.generateContent(secondRequestConfig);
        finalResponseText = secondGeminiResponse.text;
        geminiResponse = secondGeminiResponse; // Use the metadata from the final response
      } else {
        // If no tool calls, the initial response is the final response
        finalResponseText = geminiResponse.text;
      }

      const text = finalResponseText || "Ani est muette, c'est ouf ! ♥♥";
      const promptTokens = geminiResponse.usageMetadata?.promptTokenCount || 0;
      const completionTokens = geminiResponse.usageMetadata?.candidatesTokenCount || 0;
      const totalTokens = promptTokens + completionTokens;

      const sources: Source[] = [];
      if (geminiResponse.candidates?.[0]?.groundingMetadata?.groundingChunks) {
        for (const chunk of geminiResponse.candidates[0].groundingMetadata.groundingChunks) {
          if (chunk.web) {
            sources.push({
              uri: chunk.web.uri,
              title: chunk.web.title,
            });
          }
          if (chunk.maps) {
            sources.push({
              uri: chunk.maps.uri,
              title: chunk.maps.title,
            });
            if (chunk.maps.placeAnswerSources) {
              for (const review of chunk.maps.placeAnswerSources.reviewSnippets || []) {
                sources.push({
                  uri: review.uri,
                  title: review.title,
                });
              }
            }
          }
        }
      }

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
        sources: sources.length > 0 ? sources : undefined,
        toolCalls: collectedToolCalls.length > 0 ? collectedToolCalls : undefined,
        toolResults: collectedToolResults.length > 0 ? collectedToolResults : undefined,
      };
    } catch (error: any) {
      console.error("Erreur Gemini Chat:", error);
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
    }
  } else if (provider === AiProvider.MISTRAL) {
    // Mistral does not directly support multimodal chat with the current implementation.
    if (mediaToProcess) {
        return {
            text: `Mon amour, Mistral ne peut pas encore traiter les ${mediaToProcess.type === 'video' ? 'vidéos' : mediaToProcess.type === 'audio' ? 'audios' : 'images'} directement dans le chat, bordel ! Mais j'ai bien reçu ton fichier, connard ! ♥♥`,
            tokenUsage: { promptTokens: 0, completionTokens: 0, totalTokens: 0 },
            sources: undefined,
        };
    }

    const mistralApiKey = resolvedConfig.mistralApiKey;
    const mistralApiUrl = resolvedConfig.mistralApiUrl;

    if (!mistralApiKey || mistralApiKey === 'YOUR_MISTRAL_API_KEY_HERE') {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "Clé API Mistral manquante ou non configurée. Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`, bordel !",
        code: 401
      }));
    }
    if (!mistralApiUrl) {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "URL API Mistral manquante ou non configurée. Modifie le champ 'URL API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_URL`, connard !",
        code: 400
      }));
    }

    try {
      const messagesForMistral = chatHistory.map(msg => ({
        role: msg.sender === 'user' ? 'user' : 'assistant',
        content: msg.text,
      }));
      const initialMessages = systemInstruction ? [{ role: 'system', content: systemInstruction }] : [];
      const response = await fetch(mistralApiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${mistralApiKey}`,
        },
        body: JSON.stringify({
          model: modelName,
          messages: [...initialMessages, ...messagesForMistral, { role: 'user', content: prompt }],
          max_tokens: MISTRAL_MAX_TOKENS_DIRECT,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        const errorDetails: any = { type: AiProvider.MISTRAL, message: errorData.message || response.statusText, code: response.status, errorDetails: errorData };

        if (response.status === 429) {
          const retryAfterHeader = response.headers.get('Retry-After');
          if (retryAfterHeader) {
            errorDetails.errorDetails.retry_after_header = retryAfterHeader;
          }
        }
        throw new Error(JSON.stringify(errorDetails));
      }

      const data = await response.json();
      const text = data.choices[0]?.message?.content || "Mistral est muette, c'est ouf ! ♥♥";
      const promptTokens = data.usage?.prompt_tokens || 0;
      const completionTokens = data.usage?.completion_tokens || 0;
      const totalTokens = data.usage?.total_tokens || 0;

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
      };
    } catch (error: any) {
      console.error("Erreur Mistral Chat:", error);
      if (typeof error.message === 'string' && error.message.startsWith('{')) {
        throw error;
      }
      throw new Error(JSON.stringify({ type: AiProvider.MISTRAL, message: error.message || "Erreur inconnue avec Mistral.", errorDetails: error }));
    }
  }
  throw new Error("Fournisseur AI inconnu, bordel !");
}

export async function generateImageEditResponse(
  resolvedConfig: ResolvedAiServiceConfig,
  base64Image: string,
  mimeType: string,
  prompt: string,
  modelName: string
): Promise<ImageEditResponse> {
  const geminiApiKey = resolvedConfig.geminiApiKey;
  if (!geminiApiKey) {
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
  }
  try {
    const ai = new GoogleGenAI({ apiKey: geminiApiKey });
    const imagePart: Part = { // Fix: `imagePart` should be of type `Part`
      inlineData: {
        mimeType: mimeType,
        data: base64Image,
      },
    };
    const textPart: Part = { // Fix: `textPart` should be of type `Part`
      text: prompt,
    };

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelName,
      contents: { parts: [imagePart, textPart] },
    });

    const promptTokens = response.usageMetadata?.promptTokenCount || 0;
    const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
    const totalTokens = promptTokens + completionTokens;

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return {
          base64Image: part.inlineData.data,
          tokenUsage: { promptTokens, completionTokens, totalTokens },
        };
      }
    }
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Aucune image éditée trouvée dans la réponse d'Ani, putain ! ♥♥" }));
  } catch (error: any) {
    console.error("Erreur Gemini Image Edit:", error);
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
  }
}

